import subprocess as sp, json
def inline_obj(obj):
    inp=json.dumps([obj],separators=(',',':'))
    p=sp.run(["./executable","."], input=inp.encode(), capture_output=True, timeout=2)
    out=p.stdout.decode().strip().splitlines()
    return len(out)==3

def threshold(make, lo=0, hi=200):
    # find max passing
    for n in range(lo,hi+1):
        if not inline_obj(make(n)):
            return n-1
    return hi

for nkeys in [1,2,3]:
    def make(s, nkeys=nkeys):
        o={}
        o['a']="x"*s
        for i in range(1,nkeys): o[chr(97+i)]=i
        return o
    print(f"keys={nkeys} first string max inline len", threshold(make,0,120))
for nkeys in [1,2,3]:
    def make(s, nkeys=nkeys):
        o={}
        for i in range(nkeys): o[chr(97+i)]="x"*s
        return o
    print(f"keys={nkeys} all strings len max", threshold(make,0,120))
for nkeys in [1,2,3]:
    def make(s, nkeys=nkeys):
        o={}
        o['a']=int("1"* (s if s>0 else 1)) # digits s, careful s0
        for i in range(1,nkeys): o[chr(97+i)]=i
        return o
    print(f"keys={nkeys} number digits max", threshold(make,1,120))

# key length threshold depends on number keys / string value?
for nkeys in [1,2,3]:
    def make(s,nkeys=nkeys):
        o={"k"*s:1}
        for i in range(1,nkeys): o[chr(97+i)]=i
        return o
    print(f"keys={nkeys} first key max len", threshold(make,0,30))
for v in [1,"x"*20,"x"*50]:
    def make(s,v=v): return {"k"*s:v}
    print(f"key max len with value {v!r:.20}", threshold(make,0,30))
PY
