import pty, os, subprocess as sp, select, fcntl, termios, struct, sys
def run_pty(args, inp=b'', env=None):
    mout,sout=pty.openpty(); merr,serr=pty.openpty()
    e=os.environ.copy(); e["TERM"]="xterm-256color"
    if env: e.update(env)
    fcntl.ioctl(sout, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,0,0))
    p=sp.Popen(["./executable"]+args, stdin=sp.PIPE, stdout=sout, stderr=serr, env=e)
    os.close(sout); os.close(serr)
    try: p.stdin.write(inp); p.stdin.close()
    except BrokenPipeError: pass
    out=b''; err=b''; fds=[mout,merr]
    while fds:
        r,_,_=select.select(fds,[],[],0.5)
        if not r:
            if p.poll() is not None: break
            continue
        for fd in r:
            try: data=os.read(fd,65536)
            except OSError: data=b''
            if not data: fds.remove(fd)
            elif fd==mout: out+=data
            else: err+=data
    p.wait(timeout=3); os.close(mout); os.close(merr)
    print("ARGS",args,"ENV",env,"EXIT",p.returncode); print("OUT",repr(out)); print("ERR",repr(err))
if __name__=="__main__":
