import math

def js_number_to_string(x):
    """ECMAScript Number::toString() for a Python float/int."""
    if isinstance(x, bool):
        x = int(x)
    if isinstance(x, int):
        # JS numbers that happen to be Python ints should format in decimal
        # unless their magnitude forces float semantics (caller normally
        # stores JS numbers as floats/ints within safe range).
        return str(x)
    if math.isnan(x):
        return "NaN"
    if math.isinf(x):
        return "Infinity" if x > 0 else "-Infinity"
    if x == 0:
        return "0"
    sign = ""
    if x < 0:
        sign = "-"
        x = -x
    # Get shortest decimal digits via repr (Python uses a shortest
    # round-trip algorithm, like JS engines).  Parse it into a digit
    # string s and decimal point position n such that
    # value = int(s) * 10**(n-len(s)).
    r = repr(x).lower()
    if 'e' in r:
        mant, ex = r.split('e')
        ex = int(ex)
    else:
        mant, ex = r, 0
    if '.' in mant:
        a, b = mant.split('.')
        digits = a + b
        # value = digits * 10**(ex-len(b)); n = len(a)+ex, but leading
        # zeroes in a (for a == "0") need care.
        n = len(a) + ex
        if a.strip('0') == '':
            # 0.000ddd: find first non-zero in b
            i = 0
            while i < len(b) and b[i] == '0':
                i += 1
            # digits begin at 10**-(i+1)
            n = -i + ex if False else ex - i
            digits = (a + b)
        # strip leading zeroes, adjusting n
        stripped = digits.lstrip('0')
        lead = len(digits) - len(stripped)
        # Each leading zero removed decreases n by its position count
        # For values >=1, lead is 0. For 0.00ddd, digits="000ddd",
        # n computed as 1+ex, correct n is 1+ex-lead.
        n = (len(a) + ex) - lead
        digits = stripped
    else:
        digits = mant.lstrip('0') or '0'
        n = len(mant) + ex
        # account leading zeros (only possible if mant is "0")
        if mant.strip('0') == '':
            n = 1
    digits = digits.rstrip('0') or '0'
    # If repr was e.g. 1e+16, digits="1", n should be 17.
    # Verify n using ex in simple integer-mantissa case handled above.
    k = len(digits)
    if k <= n <= 21:
        return sign + digits + ('0' * (n - k))
    if 0 < n < k and n <= 21:
        return sign + digits[:n] + '.' + digits[n:]
    # Actually condition in spec is 0 < n <= 21 for above; handled.
    if -6 < n <= 0:
        return sign + '0.' + ('0' * (-n)) + digits
    # exponential
    e = n - 1
    if k == 1:
        m = digits
    else:
        m = digits[0] + '.' + digits[1:]
    return sign + m + 'e' + ('+' if e >= 0 else '-') + str(abs(e))

def js_number_radix(x, radix):
    if isinstance(x, float):
        if math.isnan(x): return "NaN"
        if math.isinf(x): return "Infinity" if x > 0 else "-Infinity"
        if x == 0: return "0"
    if radix == 10:
        return js_number_to_string(x)
    sign = '-' if x < 0 else ''
    x = abs(x)
    # Integer part
    if isinstance(x, float):
        ip = int(x)
        frac = x - ip
    else:
        ip = int(x); frac = 0.0
    digs = "0123456789abcdefghijklmnopqrstuvwxyz"
    if ip == 0:
        s = '0'
    else:
        out = []
        while ip:
            ip, rem = divmod(ip, radix)
            out.append(digs[rem])
        s = ''.join(reversed(out))
    if frac:
        out = []
        # produce digits until exact-ish / long enough like implementations
        seen = 0
        while frac and seen < 1100:
            frac *= radix
            d = int(frac)
            if d >= radix: d = radix - 1
            out.append(digs[d])
            frac -= d
            seen += 1
            # Avoid infinite trailing for repeating; stop when remainder tiny
            # in terms of double precision.
            if frac and abs(frac) < 1e-18:
                break
        # Goja/other engines produce a long exact expansion; tests rarely use.
        s += '.' + ''.join(out)
    return sign + s

def quote_json_string(s):
    """Quote a JS string the way fx's Stringify does (Go encoding/json
    with HTML escaping disabled).  s is an internal JS string, already
    scheduled to be normalised for lone surrogates by caller if needed."""
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\b': out.append('\\b')
        elif ch == '\f': out.append('\\f')
        elif ch == '\n': out.append('\\n')
