    # s may contain surrogate pairs if caller uses code-unit form; combine.
    # Our internal strings are Python unicode (astral chars single units),
    # except lone surrogates produced by slicing.
    for ch in s:
        o = ord(ch)
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\b': out.append('\\b')
        elif ch == '\f': out.append('\\f')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif ch == '\t': out.append('\\t')
        elif o < 0x20 or o == 0x7f: out.append('\\u%04x' % o)
