    out.append('"')
    return ''.join(out)

# Use the second implementation.
quote_json_string = _quote_json_string2

def escaped_len_bytes(s):
    """Length in bytes of the *contents* of quote_json_string(s),
    counting UTF-8 bytes for non-ASCII (lone surrogates as U+FFFD)."""
    q = quote_json_string(s)
    inner = q[1:-1]
    return len(inner.encode('utf-8', 'surrogatepass').replace(b'\xed\xa0\x80', b'\xef\xbf\xbd'))

def normalize_js_string(s):
    """Convert lone surrogates to U+FFFD, as Go strings do."""
    if not isinstance(s, str):
        return s
    out = []
    for ch in s:
        o = ord(ch)
        if 0xD800 <= o <= 0xDFFF:
            out.append('\ufffd')
        else:
