            pos = eff-line_start
            if pos<0: pos=0
            if pos>len(line): pos=len(line)
        # decode line for rune positions (utf-8; invalid bytes -> one replacement per byte approx via latin fallback)
        try:
            line_text = line.decode('utf-8')
            # map byte pos to rune pos
            prefix_text = line[:pos].decode('utf-8')
        except UnicodeDecodeError:
            line_text = line.decode('utf-8','surrogateescape')
            prefix_text = line[:pos].decode('utf-8','surrogateescape')
        pos_runes = len(prefix_text)
        dots_full = _disp_width_text(prefix_text)
        # segment
        if len(line_text) <= 58:
            seg_text=line_text; dots=dots_full
        else:
            if pos_runes <= 28:
                start=0
            else:
                start=pos_runes-28
            seg_text=line_text[start:start+58]
            dots=_disp_width_text(line_text[start:pos_runes]) if pos_runes>start else 0
        seg = seg_text.encode('utf-8','surrogateescape')
        text = (msg + (" on line %d.\n\n  " % line_no)).encode('utf-8','surrogateescape') + seg + b"\n  " + b'.'*dots + b"^\n\n"
        raise JsonParseError(text.decode('utf-8','surrogateescape'))

    def err_unexpected(self, context=""):
        c=self.ch
        suffix = (" "+context) if context else ""
        self.error("Unexpected character %s%s" % (go_quote_rune(c), suffix))
    def err_invalid(self, context=""):
        c=self.ch
        suffix = (" "+context) if context else ""
        self.error("Invalid character %s%s" % (go_quote_rune(c), suffix))

    # ---- whitespace / comments ----
    def skip_ws(self):
        while True:
            c=self.ch
            if c in (0x20,0x09,0x0d,0x0a):
                self.advance(); continue
            if c==0x2f: # '/'
                self.skip_comment(); continue
            break

    def skip_comment(self):
        # current ch == '/'
        if self.strict:
            self.error("Comments are not allowed in strict mode")
        self.advance()  # char after /
        c=self.ch
        if c==0x2f:  # //
            while True:
                if self.at_end():
                    break
                if self.ch==0x0a:
                    break
                self.advance()
            return
        elif c==0x2a:  # /*
            while True:
                self.advance()
                if self.at_end():
                    self.error("Unexpected end of input in comment")
                if self.ch==0x2a:
                    self.advance()
                    if self.at_end() and self.i>=len(self.data):
                        self.error("Unexpected end of input in comment")
                    if self.ch==0x2f:
                        self.advance(); return
                    if self.i>=len(self.data) or (self.i < len(self.data) and self.data[self.i]==0):
                        self.error("Unexpected end of input in comment")
            return
        else:
            # Invalid comment: '/X' where X is raw char (byte-as-rune)
            if self.i>=len(self.data):
                chs='\x00'
            else:
                chs=chr(c) if c<128 else chr(c)
            self.error("Invalid comment: '/%s'" % chs)

    # ---- entry point ----
    def next_value(self):
        if self.done:
            return None
        if self.i>=len(self.data):
            return None
        self.skip_ws()
        if self.i>=len(self.data):
            if self.emitted==0:
                self.err_unexpected()
            self.done=True
            return None
        # An actual NUL byte here: parse_value will error as unexpected.
        node=self.parse_value()
        self.emitted+=1
        return node

    def __iter__(self):
        while True:
            n=self.next_value()
            if n is None:
                return
            yield n

    # ---- values ----
    def parse_value(self):
        self.skip_ws()
        c=self.ch
        if c==0x7b: return self.parse_object()
        if c==0x5b: return self.parse_array()
        if c==0x22:
            raw=self.parse_string_raw()
            return Node(STRING, raw)
        if c==0x2d or (0x30<=c<=0x39):
            return self.parse_number()
        if c==ord('t'):
            return self.parse_keyword(b'true', BOOL, True, in_keyword=True)
        if c==ord('f'):
            return self.parse_keyword(b'false', BOOL, False, in_keyword=True)
        if c==ord('u'):
            if self.strict:
                self.err_unexpected()
            return self.parse_keyword(b'undefined', SPECIAL, b'undefined', in_keyword=True)
        if c==ord('n'):
            return self.parse_keyword(b'null', NULL, None, in_keyword=False)
        if c==ord('N'):
            if self.strict:
                self.err_unexpected()
            return self.parse_keyword(b'NaN', SPECIAL, b'NaN', in_keyword=False)
        if c==ord('I'):
            if self.strict:
                self.err_unexpected()
            return self.parse_keyword(b'Infinity', SPECIAL, b'Infinity', in_keyword=False)
        self.err_unexpected()

    def _delimiter_ok(self):
        if self.i>=len(self.data):
            return True
        return self.ch in (0x20,0x09,0x0d,0x0a,0x2c,0x5d,0x7d)

    def parse_keyword(self, word, kind, val, in_keyword):
        # current char is word[0]
        for expected in word[1:]:
            self.advance()
            if self.ch != expected:
                if in_keyword:
                    self.err_unexpected("in keyword")
                else:
                    self.err_unexpected()
        self.advance()
        if not self._delimiter_ok():
            if in_keyword:
                self.err_unexpected("in keyword")
            else:
                self.err_unexpected()
        if kind==BOOL:
            return Node(BOOL, word)
        if kind==NULL:
            return Node(NULL, b'null')
        return Node(SPECIAL, word)

    def parse_number(self):
        start=self.i
        if self.ch==0x2d:  # -
            self.advance()
            if not self.strict and self.ch in (ord('I'),ord('N')):
                w = b'Infinity' if self.ch==ord('I') else b'NaN'
                for expected in w[1:]:
                    self.advance()
                    if self.ch != expected:
                        self.err_unexpected()
                self.advance()
                if not self._delimiter_ok():
                    self.err_unexpected()
