import re

class JsonParseError(Exception):
    pass

class GoPanic(Exception):
    def __init__(self, message, frames=None):
        super().__init__(message)
        self.message = message
        self.frames = frames or []

# Node kinds
OBJECT='object'; ARRAY='array'; STRING='string'; NUMBER='number'; BOOL='bool'; NULL='null'; SPECIAL='special'

class Node:
    __slots__=('kind','value_raw','key_raw','children','key','slurp','raw_string_value')
    def __init__(self, kind, value_raw=None, children=None):
        self.kind=kind
        self.value_raw=value_raw  # bytes for scalar tokens (incl quotes for strings)
        self.key_raw=None       # bytes incl quotes
        self.children=children if children is not None else ([] if kind in (OBJECT,ARRAY) else None)
        self.key=None           # decoded key cache (str) for object children
        self.slurp=False
        self.raw_string_value=None  # for raw-line string nodes: the line str
    def __repr__(self):
        return f"Node({self.kind},{self.value_raw!r},{self.children!r})"

def go_quote_rune(b):
    """Approximate Go %q formatting for a rune given as a byte value (int)
    or a one-char str."""
    if isinstance(b, (bytes, bytearray)):
        b = b[0] if b else 0
    if isinstance(b, str):
        cp = ord(b) if b else 0
        ch = b
    else:
        cp = b
        ch = chr(b) if b is not None else '\x00'
    if cp == 0:
        inner = "\\x00"
    elif ch == "'":
        inner = "\\'"
    elif ch == "\\":
        inner = "\\\\"
    elif ch == '\a': inner='\\a'
    elif ch == '\b': inner='\\b'
    elif ch == '\f': inner='\\f'
    elif ch == '\n': inner='\\n'
    elif ch == '\r': inner='\\r'
    elif ch == '\t': inner='\\t'
    elif ch == '\v': inner='\\v'
    elif cp < 0x20 or cp == 0x7f:
        inner = "\\x%02x" % cp
    elif cp < 0x80:
        inner = ch
    else:
        # byte-as-rune: cp is the byte value (<256) for parser bytes >=128;
        # Go prints that rune (e.g. Ã).
        if cp <= 0xff:
            inner = chr(cp)
        else:
            inner = ch if ch.isprintable() else ("\\u%04x" % cp)
    return "'" + inner + "'"

def _disp_width_text(s):
    import unicodedata
    w=0
    for ch in s:
        o=ord(ch)
        if o < 0x20 or o==0x7f:
            continue
        if unicodedata.combining(ch):
            continue
        if unicodedata.category(ch) in ('Mn','Me','Cf') and ch not in ('\u200d',):
            # Zero-width-ish; ZWJ itself is 0 too in go-runewidth
            continue
        eaw = unicodedata.east_asian_width(ch)
        if eaw in ('W','F'):
            w+=2
        elif o>=0x1F300 or (0x2600<=o<=0x27BF) or o>=0x1F000:
            w+=2
        else:
            w+=1
    return w

