        return self.data[self.i] if self.i < len(self.data) else 0
    def at_end(self):
        return self.i >= len(self.data) or (self.i < len(self.data) and self.data[self.i]==0)
    def advance(self):
        if self.i < len(self.data):
            self.i += 1
        return self.ch

    def error(self, msg, at_index=None):
