            line_start = data.rfind(b'\n', 0, eff+1 if eff < len(data) else len(data))
            # rfind inclusive: if char at eff is '\n' itself we want previous line; errors don't point at \n normally
            if eff < len(data) and data[eff:eff+1]==b'\n':
                line_start = data.rfind(b'\n',0,eff)
            line_start = line_start+1
            line_end = data.find(b'\n', line_start)
            if line_end<0: line_end=len(data)
            line = data[line_start:line_end]
            line_no = data.count(b'\n',0,line_start)+1
            pos = eff-line_start
            if pos<0: pos=0
            if pos>len(line): pos=len(line)
