            return self.parse_keyword(b'undefined', SPECIAL, b'undefined', in_keyword=True)
        if c==ord('n'):
            return self.parse_keyword(b'null', NULL, None, in_keyword=False)
        if c==ord('N'):
            if self.strict:
                self.err_unexpected()
            return self.parse_keyword(b'NaN', SPECIAL, b'NaN', in_keyword=False)
        if c==ord('I'):
            if self.strict:
                self.err_unexpected()
            return self.parse_keyword(b'Infinity', SPECIAL, b'Infinity', in_keyword=False)
        self.err_unexpected()

    def _delimiter_ok(self):
        if self.i>=len(self.data):
            return True
        return self.ch in (0x20,0x09,0x0d,0x0a,0x2c,0x5d,0x7d)

    def parse_keyword(self, word, kind, val, in_keyword):
        # current char is word[0]
        for expected in word[1:]:
            self.advance()
            if self.ch != expected:
                if in_keyword:
                    self.err_unexpected("in keyword")
                else:
                    self.err_unexpected()
        self.advance()
        if not self._delimiter_ok():
            if in_keyword:
                self.err_unexpected("in keyword")
            else:
                self.err_unexpected()
        if kind==BOOL:
            return Node(BOOL, word)
        if kind==NULL:
            return Node(NULL, b'null')
        return Node(SPECIAL, word)

    def parse_number(self):
        start=self.i
        if self.ch==0x2d:  # -
            self.advance()
            if not self.strict and self.ch in (ord('I'),ord('N')):
                w = b'Infinity' if self.ch==ord('I') else b'NaN'
                for expected in w[1:]:
                    self.advance()
                    if self.ch != expected:
                        self.err_unexpected()
                self.advance()
                if not self._delimiter_ok():
                    self.err_unexpected()
                return Node(SPECIAL, self.data[start:self.i])
            if not (0x30<=self.ch<=0x39):
                self.err_invalid("in number")
        # int part
        if self.ch==0x30:
            self.advance()
        elif 0x31<=self.ch<=0x39:
            while 0x30<=self.ch<=0x39:
                self.advance()
        else:
            self.err_invalid("in number")
        # fraction
        if self.ch==0x2e:
            self.advance()
            if not (0x30<=self.ch<=0x39):
                self.err_invalid("in number")
            while 0x30<=self.ch<=0x39:
                self.advance()
        # exponent
        if self.ch in (ord('e'),ord('E')):
            self.advance()
            if self.ch in (ord('+'),ord('-')):
                self.advance()
            if not (0x30<=self.ch<=0x39):
                self.err_invalid("in number")
            while 0x30<=self.ch<=0x39:
                self.advance()
        return Node(NUMBER, self.data[start:self.i])

    def parse_string_raw(self):
        # current ch is opening quote
        start=self.i
        self.advance()
        while True:
            if self.at_end():
                self.error("Unexpected end of input in string")
            c=self.ch
            if c==0x22:
                self.advance()
                return self.data[start:self.i]
            if c==0x5c:  # backslash
                self.advance()
                if self.i>=len(self.data):
                    self.error("Unexpected end of input in string")
                e=self.ch
                if self.strict:
                    if e in (0x22,0x5c,0x2f,ord('b'),ord('f'),ord('n'),ord('r'),ord('t')):
                        self.advance(); continue
                    elif e==ord('u'):
                        seq=bytearray(b'\\u')
                        ok=True
                        for _ in range(4):
                            self.advance()
                            if self.i>=len(self.data):
                                self.error("Unexpected end of input in string")
                            seq.append(self.ch if self.ch<128 else 0x3f)
                            h=self.ch
                            if not ((0x30<=h<=0x39) or (ord('a')<=h<=ord('f')) or (ord('A')<=h<=ord('F'))):
                                self.error("Invalid Unicode escape sequence '%s'" % seq.decode('ascii','replace'))
                        self.advance(); continue
                    else:
                        chs=chr(e) if e<0x110000 else '?'
                        self.error("Invalid escape sequence '\\%s'" % chs)
                else:
                    self.advance(); continue
            else:
                self.advance()

    def parse_object(self):
        node=Node(OBJECT, None, [])
        self.advance()  # {
        self.skip_ws()
        if self.ch==0x7d:
            self.advance(); return node
        while True:
            if self.ch != 0x22:
                self.error("Expected object key to be a string, got %s" % go_quote_rune(self.ch))
            key_raw=self.parse_string_raw()
            self.skip_ws()
            if self.ch != 0x3a:
                self.error("Expected colon after object key, got %s" % go_quote_rune(self.ch))
            self.advance()
            child=self.parse_value()
            child.key_raw=key_raw
            node.children.append(child)
            self.skip_ws()
            if self.ch==0x2c:
                comma_i=self.i
                self.advance(); self.skip_ws()
                if self.ch==0x7d:
                    if self.strict:
                        self.error("Trailing comma is not allowed in strict mode", at_index=comma_i)
                    self.advance(); return node
                continue
            elif self.ch==0x7d:
                self.advance(); return node
            else:
                self.err_unexpected("in object")

    def parse_array(self):
        node=Node(ARRAY, None, [])
        self.advance()  # [
        self.skip_ws()
        if self.ch==0x5d:
            self.advance(); return node
        while True:
            child=self.parse_value()
            node.children.append(child)
            self.skip_ws()
            if self.ch==0x2c:
                comma_i=self.i
                self.advance(); self.skip_ws()
                if self.ch==0x5d:
                    if self.strict:
                        self.error("Trailing comma is not allowed in strict mode", at_index=comma_i)
                    self.advance(); return node
                continue
            elif self.ch==0x5d:
                self.advance(); return node
            else:
                self.err_invalid("in array")

# ---- String decoding helpers ----

class StringDecodePanic(Exception):
    pass

def decode_json_string_token_go(raw):
    """Decode a JSON string token (bytes incl quotes) the way Go's
    encoding/json does (used in Node.ToValue).  Raises StringDecodePanic
    with a Go json-style message on invalid escapes/controls."""
    if isinstance(raw, str):
        raw=raw.encode('utf-8','surrogateescape')
    assert raw[:1]==b'"'
    out=[]
    i=1
    n=len(raw)
    while i<n:
        b=raw[i]
        if b==0x22:
            return ''.join(out)
        if b==0x5c:
            i+=1
            if i>=n: break
            e=raw[i]
            mp={0x22:'"',0x5c:'\\',0x2f:'/',ord('b'):'\b',ord('f'):'\f',ord('n'):'\n',ord('r'):'\r',ord('t'):'\t'}
            if e in mp:
                out.append(mp[e]); i+=1; continue
            if e==ord('u'):
                if i+4>=n:
                    raise StringDecodePanic("invalid character '%s' in \\u hexadecimal character escape" % chr(raw[i+1] if i+1<n else 0))
                hexs=raw[i+1:i+5]
                try:
                    cp=int(hexs.decode('ascii'),16)
                except Exception:
                    # find bad char
                    for hb in hexs:
                        if chr(hb) not in '0123456789abcdefABCDEF':
                            raise StringDecodePanic("invalid character '%s' in \\u hexadecimal character escape" % chr(hb))
                    raise StringDecodePanic("invalid character in \\u hexadecimal character escape")
                i+=5
                if 0xD800<=cp<=0xDBFF:
                    # try pair
                    if raw[i:i+2]==b'\\u':
                        hex2=raw[i+2:i+6]
                        try:
                            cp2=int(hex2.decode('ascii'),16)
                        except Exception:
                            cp2=None
                        if cp2 is not None and 0xDC00<=cp2<=0xDFFF:
                            out.append(chr(0x10000+((cp-0xD800)<<10)+(cp2-0xDC00)))
                            i+=6; continue
                    out.append('\ufffd'); continue
                if 0xDC00<=cp<=0xDFFF:
                    out.append('\ufffd'); continue
                out.append(chr(cp)); continue
            raise StringDecodePanic("invalid character '%s' in string escape code" % (chr(e) if 32<=e<127 else ('\\x%02x'%e)))
        if b<0x20:
            raise StringDecodePanic("invalid character '\\x%02x' in string literal" % b)
        if b<0x80:
            out.append(chr(b)); i+=1; continue
        # UTF-8 sequence; Go json replaces invalid bytes with U+FFFD
        # Determine length
        if b>=0xF0: ln=4
        elif b>=0xE0: ln=3
        else: ln=2
        seq=raw[i:i+ln]
        try:
            s=seq.decode('utf-8')
            if len(s)!=1: raise ValueError
            out.append(s); i+=ln
        except Exception:
            out.append('\ufffd'); i+=1
    return ''.join(out)

def decode_node_key(node):
    if node.key is not None:
        return node.key
    try:
        node.key=decode_json_string_token_go(node.key_raw)
    except StringDecodePanic as e:
        raise GoPanic(str(e))
    return node.key

def go_unquote(raw):
    """Equivalent of Go strconv.Unquote for a double-quoted token.
    raw: bytes or str incl surrounding quotes.  Returns Python str.
    Raises ValueError('invalid syntax') style on failure."""
    if isinstance(raw, (bytes,bytearray)):
        # Go Unquote operates on byte string; escapes produce bytes/runes.
        # Work on bytes, decode resulting byte string as utf-8/surrogateescape at end.
        data=bytes(raw)
        if len(data)<2 or data[0]!=0x22 or data[-1]!=0x22:
            raise ValueError("invalid syntax")
        body=data[1:-1]
        out=bytearray()
        i=0
        while i<len(body):
            b=body[i]
            if b==0x0a:
                raise ValueError("invalid syntax")
            if b!=0x5c:
                out.append(b); i+=1; continue
            i+=1
            if i>=len(body): raise ValueError("invalid syntax")
            e=body[i]; i+=1
            simple={ord('a'):7,ord('b'):8,ord('f'):12,ord('n'):10,ord('r'):13,ord('t'):9,ord('v'):11,0x5c:0x5c}
            if e in simple:
                out.append(simple[e]); continue
            if e==0x22:
                out.append(0x22); continue
            if e==ord('x'):
                if i+2>len(body): raise ValueError("invalid syntax")
                try: out.append(int(body[i:i+2].decode('ascii'),16))
                except Exception: raise ValueError("invalid syntax")
                i+=2; continue
            if e==ord('u'):
                if i+4>len(body): raise ValueError("invalid syntax")
                try: cp=int(body[i:i+4].decode('ascii'),16)
                except Exception: raise ValueError("invalid syntax")
                i+=4
                if 0xD800<=cp<=0xDFFF: raise ValueError("invalid syntax")
                out.extend(chr(cp).encode('utf-8')); continue
            if e==ord('U'):
                if i+8>len(body): raise ValueError("invalid syntax")
                try: cp=int(body[i:i+8].decode('ascii'),16)
                except Exception: raise ValueError("invalid syntax")
                i+=8
                if cp>0x10FFFF or 0xD800<=cp<=0xDFFF: raise ValueError("invalid syntax")
                out.extend(chr(cp).encode('utf-8')); continue
            if ord('0')<=e<=ord('7'):
                # octal: need exactly 3 digits total including e, value <=255
                digs=[e]
                for _ in range(2):
                    if i<len(body) and ord('0')<=body[i]<=ord('7'):
                        digs.append(body[i]); i+=1
                    else:
                        raise ValueError("invalid syntax")
                val=int(bytes(digs).decode('ascii'),8)
                if val>255: raise ValueError("invalid syntax")
                out.append(val); continue
            if e==0x0a:
                # backslash-newline: Go string literals don't allow unescaped
                # newlines even after backslash? \ followed by newline is invalid.
                raise ValueError("invalid syntax")
            raise ValueError("invalid syntax")
        return out.decode('utf-8','surrogateescape')
    else:
        return go_unquote(raw.encode('utf-8','surrogateescape'))
