class PrintConfig:
    def __init__(self, inline=True, theme="1", colors=False):
        self.inline=inline
        self.theme=theme if theme in THEMES else "1"
        self.colors=colors
    def style(self, text, code):
        if isinstance(text,str):
            b=text.encode('utf-8','surrogateescape')
        else:
            b=bytes(text)
        if not self.colors or not code:
            return b
        return b"\x1b["+code.encode()+b"m"+b+b"\x1b[0m"
    def st(self, kind, text):
        code=THEMES[self.theme].get(kind,"")
        return self.style(text,code)
    def syntax(self,text): return self.st('syntax',text)
    def key(self,text): return self.st('key',text)

class PNode:
    __slots__=('kind','token','children','entries','top_raw','slurp_empty','string_value')
    def __init__(self,kind,token=None,children=None,entries=None):
        self.kind=kind
        self.token=token  # bytes, display token for leaf (quoted for strings)
        self.children=children or []
        self.entries=entries or []  # list of (key_token_bytes, PNode)
        self.top_raw=None
