def _inner_len(token):
    if token is None: return 0
    if isinstance(token,str): token=token.encode('utf-8','surrogateescape')
    if len(token)>=2 and token[:1]==b'"' and token[-1:]==b'"':
        return len(token)-2
    return len(token)

def leaf_class(p):
    if p.kind in (STR,DATESTR): return 'string'
    if p.kind==NUM: return 'number'
    if p.kind in (BOOL,NULL): return 'other'
    return 'special'

def can_inline_array(p,parent,cfg):
    if not cfg.inline: return False
    if p.kind!=ARR or len(p.children)==0: return False
    if all(c.kind==NUM for c in p.children):
        return True
    if parent=='object' and len(p.children)==1:
        c=p.children[0]
        if c.kind in (STR,DATESTR,NUM,BOOL,NULL):
            if c.kind in (STR,DATESTR) and _inner_len(c.token)>78:
                return False
            return True
    return False

def can_inline_object(p,cfg):
    if not cfg.inline: return False
    if p.kind!=OBJ: return False
    if len(p.entries)==0: return True
    for kt,child in p.entries:
        if child.kind in (OBJ,ARR,SPECIAL):
            return False
    if len(p.entries)==1:
        kt,child=p.entries[0]
        klen=_inner_len(kt)
        if child.kind in (STR,DATESTR):
            return klen + _inner_len(child.token) <= 76
        return klen<=8
    ns=0; no=0
    for kt,child in p.entries:
        if _inner_len(kt)>8: return False
        if child.kind in (STR,DATESTR):
            ns+=1
            if _inner_len(child.token)>18: return False
        else:
            no+=1
    return ns<=2 and no<=3

