def raw_node_to_pnode(node, slurp_root=False):
    if node.kind==JX.OBJECT:
        entries=[]
        for ch in node.children:
            entries.append((ch.key_raw, raw_node_to_pnode(ch)))
        return PNode(OBJ,entries=entries)
    if node.kind==JX.ARRAY:
        p=PNode(ARR,children=[raw_node_to_pnode(c) for c in node.children])
        if node.slurp and len(node.children)==0:
            p.slurp_empty=True
        return p
    if node.kind==JX.STRING:
        p=PNode(STR,token=node.value_raw if node.raw_string_value is None else quote_json_string(node.raw_string_value).encode('utf-8','surrogateescape'))
        if node.raw_string_value is not None:
            p.top_raw=node.raw_string_value.encode('utf-8','surrogateescape')
            p.string_value=node.raw_string_value
        else:
            # top_raw computed lazily via go_unquote in render_raw_top
            p.top_raw=None
        return p
    if node.kind==JX.NUMBER:
        return PNode(NUM,token=node.value_raw)
    if node.kind==JX.BOOL:
        return PNode(BOOL,token=node.value_raw)
    if node.kind==JX.NULL:
        return PNode(NULL,token=b'null')
    if node.kind==JX.SPECIAL:
        return PNode(SPECIAL,token=node.value_raw)
    return PNode(NULL,token=b'null')

def render_raw_node_top(node,cfg):
    """Render a parsed JSON node in identity (raw) mode.  May raise GoPanic
    for top-level strings whose Go-unquote fails (surrogate escapes etc)."""
    if node.kind==JX.STRING and node.raw_string_value is None:
        try:
            s=JX.go_unquote(node.value_raw)
        except ValueError:
            raise JX.GoPanic("invalid syntax", [
                "panic: invalid syntax",
                "",
                "goroutine 1 [running]:",
                "github.com/antonmedv/fx/internal/engine.Start({0xad7b20?, 0xc000000000?}, {0x0, 0x1, 0x1}, {0x0?, 0x0?, 0x0?, 0x0?})",
                "\tgithub.com/antonmedv/fx/internal/engine/engine.go:66 +0x80e",
                "main.main()",
                "\tgithub.com/antonmedv/fx/main.go:220 +0xf8b",
            ])
        return s.encode('utf-8','surrogateescape')
    p=raw_node_to_pnode(node)
    return render(p,cfg,top=True)
