        self.expect_punc(')')
        return params,rest
    def _check_duplicate_params(self,params,async_,gen):
        # Duplicate simple parameter names are compile errors in strict mode,
        # arrow functions, and functions with non-simple params.  Since the
        # wrapping script is strict, mirror the common case.
        names=[]
        def collect(p):
            if p is None: return
            if p.kind=='idpat': names.append(p)
            elif p.kind=='assignpat': collect(p.a)
            elif p.kind=='rest': collect(p.a)
            elif p.kind=='objpat':
                for pr in p.a:
                    if pr.kind=='rest': collect(pr.a)
                    else: collect(pr.b)
            elif p.kind=='arrpat':
                for e in p.a: collect(e)
        for p in params: collect(p)
        seen={}
        for p in names:
            if p.a in seen:
                # position at duplicate identifier
                t=Tok('name',p.a,p.start,p.end,0,0)
                # approximate line/col via current token's context not available; store pos and let engine recompute in full src
                raise JSSyntaxErrorEx("Duplicate parameter name not allowed in this context",p.start,'compile')
            seen[p.a]=p
    def parse_function_body(self,async_,gen):
        saved=(self.strict,self.in_function,self.in_generator,self.in_async,self.allow_yield,self.allow_await,self.allow_return,self.in_loop,self.in_switch)
        self.in_function+=1; self.in_generator=gen; self.in_async=async_; self.allow_yield=gen; self.allow_await=async_; self.allow_return=True; self.in_loop=0; self.in_switch=0
        blk=self.parse_block()
        (self.strict,self.in_function,self.in_generator,self.in_async,self.allow_yield,self.allow_await,self.allow_return,self.in_loop,self.in_switch)=saved
