    def parse_class_decl(self):
        c=self.parse_class(is_decl=True)
        return N('classdecl',c,start=c.start,end=c.end)
    def parse_class(self,is_decl=False):
        st=self.advance() # class
        name=''
        if self.tok.kind=='name' and not self.is_name('extends'):
            name=self.tok.val; self.advance()
        elif is_decl:
            self.unexpected()
        extends=None
        if self.eat_name('extends'):
            extends=self.parse_lefthand()
        self.expect_punc('{')
        elems=[]
        old_super=self.super_context; self.super_context='method'
        while not self.is_punc('}'):
            if self.at_eof(): self.unexpected()
            if self.eat_punc(';'): continue
            estart=self.tok.start
            is_static=False
            # static block / static modifier
            async_=False; gen=False; kind='method'
            # modifiers loop
            while True:
                if self.is_name('static') and not self.is_punc('(',self.peek()) and not self.is_punc('=',self.peek()) and not self.is_punc(';',self.peek()):
                    is_static=True; self.advance()
                    if self.is_punc('{'):
