                if self.is_punc('*'):
                    gen=True; self.advance(); continue
                if (self.is_name('get') or self.is_name('set')) and not self.is_punc('(',self.peek()) and not self.is_punc('=',self.peek()) and not self.is_punc(';',self.peek()):
