    # ---------- expressions ----------
    def parse_expression(self,in_ok=True):
        start=self.i
        e=self.parse_assignment(in_ok=in_ok)
        if self.is_punc(','):
            exprs=[e]
            while self.eat_punc(','):
                exprs.append(self.parse_assignment(in_ok=in_ok))
            return N('seq',exprs,start=e.start,end=exprs[-1].end)
        return e

    def parse_assignment(self,in_ok=True):
        # Arrow detection
        save=self.save()
        # single identifier =>
        if self.tok.kind=='name' and self.is_punc('=>',self.peek()):
            name_tok=self.advance(); self.advance()
            params=[N('idpat',name_tok.val,start=name_tok.start,end=name_tok.end)]
            return self.parse_arrow_rest(params,name_tok.start,async_=False)
        # async identifier / async (params) / (…) =>
        try_arrow=self._try_parse_arrow()
        if try_arrow is not None:
            return try_arrow
        self.restore(save) if try_arrow is None else None
        # yield in generator
        if self.allow_yield and self.is_name('yield'):
            yt=self.advance()
            if yt.nl: pass
            deleg=False
            if self.eat_punc('*'): deleg=True
            arg=None
            if not self.is_terminal() and not self.is_punc(',') and not self.is_punc(':'):
                arg=self.parse_assignment()
            return N('yield',arg,deleg,start=yt.start)
        e=self.parse_conditional(in_ok=in_ok)
        if self.tok.kind=='punc' and self.tok.val in ASSIGN_OPS:
            op=self.advance().val
            if e.kind in ('objlit','arrlit'):
                target=self.expr_to_pattern(e)
            else:
                target=e
                if not self.is_valid_lhs(e) and not (e.kind in ('objlit','arrlit')):
                    # e.g. 1=2, this= , function call =
                    # In strict, assignment to eval/arguments identifiers is compile-ish but goja reports Invalid left-hand side for many.
                    self.unexpected(msg="Invalid left-hand side in assignment ")
            val=self.parse_assignment(in_ok=in_ok)
            return N('assign',target,val,op,start=e.start,end=val.end)
        return e

    def _try_parse_arrow(self):
        save=self.save()
        start=self.tok.start
        async_=False
        try:
            if self.is_name('async'):
                nt=self.peek()
                if nt.nl:
                    raise _NoArrow
                if nt.kind=='name' and self.is_punc('=>',self.peek(2)):
                    self.advance(); name_tok=self.advance(); self.advance()
                    return self.parse_arrow_rest([N('idpat',name_tok.val,start=name_tok.start)],start,async_=True)
                if not self.is_punc('(',nt):
                    raise _NoArrow
                async_=True; self.advance()
            if not self.is_punc('('):
                raise _NoArrow
            params,_r=self.parse_params()
            if not self.is_punc('=>'):
                raise _NoArrow
            self.advance()
            self._check_duplicate_params(params,async_,False)
            return self.parse_arrow_rest(params,start,async_=async_)
        except _NoArrow:
            self.restore(save); return None
        except JSSyntaxErrorEx:
            # If the '(' wasn't arrow params, backtrack and let normal parse produce the relevant error.
            # But if we already saw => this shouldn't happen.
            self.restore(save); return None

    def parse_arrow_rest(self,params,start,async_=False):
        if self.is_punc('{'):
            body,ben=self.parse_function_body(async_,False)
            return N('arrow',params,body,True,{'async':async_},start=start,end=ben)
        saved=(self.allow_await,self.allow_return)
        self.allow_await=async_
        body=self.parse_assignment()
        self.allow_await,self.allow_return=saved
        return N('arrow',params,body,False,{'async':async_},start=start,end=body.end)

    def parse_conditional(self,in_ok=True):
        e=self.parse_binary(3,in_ok=in_ok)
        if self.is_punc('?'):
            self.advance()
            a=self.parse_assignment(in_ok=True)
            self.expect_punc(':')
            b=self.parse_assignment(in_ok=in_ok)
            return N('cond',e,a,b,start=e.start,end=b.end)
        return e

    def parse_binary(self,min_prec,in_ok=True):
        left=self.parse_unary()
        while True:
            op=None; prec=None; optok=self.tok
            if self.tok.kind=='punc' and self.tok.val in BIN_PREC and self.tok.val!=',':
                op=self.tok.val; prec=BIN_PREC[op]
            elif self.tok.kind=='name' and self.tok.val in ('instanceof',) :
                op=self.tok.val; prec=BIN_PREC[op]
            elif in_ok and self.tok.kind=='name' and self.tok.val=='in':
                op='in'; prec=BIN_PREC[op]
            else:
                break
            if prec<min_prec: break
            # ?? cannot mix with ||/&& without parens: enforce roughly by AST shape in interpreter/parser later (goja syntax error)
            self.advance()
            if op=='**':
                right=self.parse_assignment() if False else self.parse_binary(prec,in_ok=in_ok)  # right assoc approx
                # Exponent LHS cannot be unary in JS; check
                if left.kind=='unary':
                    self.unexpected(msg="Unexpected token ** ")
                right=self.parse_unary_rhs_for_pow(right)
            else:
                right=self.parse_binary(prec+1,in_ok=in_ok)
            kind='logical' if op in ('&&','||','??') else 'binary'
            left=N(kind,op,left,right,start=left.start,end=right.end)
        return left
    def parse_unary_rhs_for_pow(self,right):
        return right

    def parse_unary(self):
        t=self.tok
        if t.kind=='punc' and t.val in ('+','-','!','~','++','--'):
            self.advance()
            arg=self.parse_unary()
            if t.val in ('++','--'):
                if not self.is_valid_lhs(arg):
                    self.unexpected(msg="Invalid left-hand side in assignment ")
                return N('update',t.val,arg,True,start=t.start,end=arg.end)
            return N('unary',t.val,arg,start=t.start,end=arg.end)
        if t.kind=='name' and t.val in ('typeof','void','delete'):
            self.advance()
            arg=self.parse_unary()
            if t.val=='delete' and arg.kind=='id':
                # strict compile error
                raise JSSyntaxErrorEx("Delete of an unqualified identifier in strict mode",arg.start,'compile')
            return N('unary',t.val,arg,start=t.start,end=arg.end)
        if t.kind=='name' and t.val=='await' and self.allow_await:
            self.advance(); arg=self.parse_unary(); return N('await',arg,start=t.start,end=arg.end)
        if t.kind=='name' and t.val=='await' and self.in_function==0 and False:
            pass
        e=self.parse_postfix()
        return e

    def parse_postfix(self):
        e=self.parse_lefthand()
        if not self.tok.nl and self.tok.kind=='punc' and self.tok.val in ('++','--'):
            op=self.advance()
            if not self.is_valid_lhs(e):
                self.unexpected(msg="Invalid left-hand side in assignment ")
            return N('update',op.val,e,False,start=e.start,end=op.end)
        return e
