from js_lexer import Lexer, Tok, JSSyntaxErrorEx, KEYWORDS

RESERVED_STRICT={'implements','package','protected','interface','private','public','static','let'}
RESERVED_ALWAYS={'break','case','catch','class','const','continue','debugger','default','delete','do','else','export','extends','finally','for','function','if','import','in','instanceof','new','return','super','switch','this','throw','try','typeof','var','void','while','with','yield','enum'}

class N:
    __slots__=('kind','a','b','c','d','start','end')
    def __init__(self,kind,a=None,b=None,c=None,d=None,start=0,end=0):
        self.kind=kind; self.a=a; self.b=b; self.c=c; self.d=d; self.start=start; self.end=end
    def __repr__(self):
        return f"N({self.kind},{self.a!r},{self.b!r},{self.c!r})"

BIN_PREC={
 ',':0,
 # assignment handled separately
 '??':3,
 '||':4,
 '&&':5,
 '|':6,
 '^':7,
 '&':8,
 '==':9,'!=':9,'===':9,'!==':9,
 '<':10,'<=':10,'>':10,'>=':10,'in':10,'instanceof':10,
 '<<':11,'>>':11,'>>>':11,
 '+':12,'-':12,
 '*':13,'/':13,'%':13,
 '**':14,
}
ASSIGN_OPS={'=','+=','-=','*=','/=','%=','**=','<<=','>>=','>>>=','&=','|=','^=','&&=','||=','??='}

class Parser:
    def __init__(self,src,eval_direct=False,allow_return_outside=False):
        self.src=src
        self.lx=Lexer(src)
        self.toks=self.lx.tokenize()
        self.i=0
        self.strict=False
        self.in_function=0
        self.in_generator=False
        self.in_async=False
        self.allow_yield=False
        self.allow_await=False
        self.allow_return=allow_return_outside
        self.in_loop=0
        self.in_switch=0
        self.labels=[]
        self.eval_direct=eval_direct
        self.super_context=None  # 'method' if super property allowed, 'derived_ctor' etc (loosely)

    # token helpers
    @property
    def tok(self): return self.toks[self.i]
    def peek(self,n=1):
        j=self.i+n
        return self.toks[j] if j < len(self.toks) else self.toks[-1]
    def at_eof(self): return self.tok.kind=='eof'
    def is_punc(self,v,t=None):
        t=t or self.tok
        return t.kind=='punc' and t.val==v
    def is_name(self,v,t=None):
        t=t or self.tok
        return t.kind=='name' and t.val==v
    def advance(self):
        t=self.tok
        if t.kind!='eof': self.i+=1
        return t
    def eat_punc(self,v):
        if self.is_punc(v): self.advance(); return True
        return False
    def eat_name(self,v):
        if self.is_name(v): self.advance(); return True
        return False
    def expect_punc(self,v):
        if not self.is_punc(v): self.unexpected()
        return self.advance()
    def save(self):
        return (self.i,self.strict,self.in_function,self.in_generator,self.in_async,self.allow_yield,self.allow_await,self.allow_return,self.in_loop,self.in_switch,list(self.labels),self.super_context)
    def restore(self,s):
        (self.i,self.strict,self.in_function,self.in_generator,self.in_async,self.allow_yield,self.allow_await,self.allow_return,self.in_loop,self.in_switch,self.labels,self.super_context)=s

    # errors
    def tok_display(self,t):
        if t.kind=='eof': return '}'
        # EOF in goja parser messages often shows as } because expected closing brace of wrapper.
        if t.kind=='punc': return t.val
        if t.kind=='name': return t.val
        if t.kind=='illegal': return 'ILLEGAL'
        if t.kind=='str': return 'string'
        if t.kind in ('num','bigint'): return 'number'
        return str(t.val)
    def unexpected(self,t=None,category='parser',msg=None):
        t=t or self.tok
        if msg is None:
            if t.kind=='illegal':
                if getattr(t,'flags',None)=='missing_slash':
                    msg="Invalid regular expression: missing /"
                else:
                    msg="Unexpected token ILLEGAL "
            elif t.kind=='name':
                if t.val in KEYWORDS and t.val not in ('this','super'):
                    msg=f"Unexpected token {t.val} "
                else:
                    msg="Unexpected identifier"
            elif t.kind in ('num','bigint'):
                msg="Unexpected number"
            elif t.kind=='str':
                msg="Unexpected string"
            elif t.kind=='eof':
                msg="Unexpected token } "
            elif t.kind=='regex':
                msg="Unexpected token /"
            else:
                msg=f"Unexpected token {self.tok_display(t)} "
        raise JSSyntaxErrorEx(msg,t.start,category,line=t.line,col=t.col)
    def compile_error(self,msg,t=None):
        t=t or self.tok
        raise JSSyntaxErrorEx(msg,t.start,'compile',line=t.line,col=t.col)
    def check_legacy_number(self,t):
        if t.kind in ('num','bigint') and getattr(t,'flags',None):
            if t.flags=='legacy_octal':
                if self.strict:
                    raise JSSyntaxErrorEx("Octal literals are not allowed in strict mode",t.start,'compile',line=t.line,col=t.col)
            elif t.flags=='legacy_nonoctal':
