    def consume_semi(self):
        if self.is_punc(';'): self.advance(); return
        if self.at_eof() or self.is_punc('}') or self.tok.nl: return
        self.unexpected()
    def is_terminal(self):
        return self.at_eof() or self.is_punc('}') or self.tok.nl or self.is_punc(';')

    # ---------- program / statements ----------
    def parse_program(self):
        start=self.tok.start
        body=[]
        # directive prologue handled for strict setting during parse of statements:
        body=self.parse_statement_list(top=True)
        if not self.at_eof():
            self.unexpected()
        return N('program',body,start=start,end=self.toks[-1].end)

    def parse_statement_list(self,top=False,stop_rbrace=False):
        stmts=[]
        seen_directive=True
        while not self.at_eof():
            if stop_rbrace and self.is_punc('}'): break
            st=self.parse_statement()
            if st is None:
                continue
            # directive handling: a leading string literal expression statement
            if seen_directive and st.kind=='exprstmt' and st.a.kind=='literal' and isinstance(st.a.a,str) and st.a.b=='str':
                if st.a.a=='use strict':
                    self.strict=True
                stmts.append(st); continue
            seen_directive=False
            stmts.append(st)
        return stmts

    def parse_single_expression_program(self):
        # used for precheck snippets? (not main path)
        e=self.parse_expression()
        return e

    def parse_statement(self):
        t=self.tok
        if t.kind=='punc':
            if t.val==';': self.advance(); return N('empty',start=t.start,end=t.end)
            if t.val=='{': return self.parse_block()
        if t.kind=='name':
            v=t.val
            if v=='var' or v=='const': return self.parse_var_decl_stmt()
            if v=='let':
                # let declaration if followed by identifier, [, { ; in sloppy let can be identifier.
                nt=self.peek()
                if nt.kind=='name' and nt.val not in RESERVED_ALWAYS or (nt.kind=='punc' and nt.val in ('[','{')):
                    return self.parse_var_decl_stmt()
                if self.strict and nt.kind=='name':
                    return self.parse_var_decl_stmt()
                # identifier expression
            if v=='function': return self.parse_function_decl()
            if v=='class': return self.parse_class_decl()
            if v=='if': return self.parse_if()
            if v=='while': return self.parse_while()
            if v=='do': return self.parse_do()
            if v=='for': return self.parse_for()
            if v=='switch': return self.parse_switch()
            if v=='try': return self.parse_try()
            if v=='throw':
                self.advance()
                if self.tok.nl: self.unexpected(msg="Unexpected token } ")
                e=self.parse_expression(); self.consume_semi(); return N('throw',e,start=t.start,end=e.end)
