                if not self.allow_return and self.in_function==0:
                    # Goja parser says Unexpected token return in reducer wrapper because return is consumed by wrapper's own return; in general scripts it's compile-ish. Keep parser message.
                    self.unexpected(msg="Unexpected token return ")
                self.advance()
                if self.is_terminal():
                    if self.is_punc(';'): self.advance()
                    return N('return',None,start=t.start,end=t.end)
                e=self.parse_expression(); self.consume_semi(); return N('return',e,start=t.start,end=e.end)
            if v=='break' or v=='continue':
                self.advance()
                label=None
                if not self.is_terminal() and self.tok.kind=='name':
                    label=self.tok.val; self.advance()
                self.consume_semi()
                return N(v,label,start=t.start,end=t.end)
