        e=self.parse_expression()
        self.consume_semi()
        return N('exprstmt',e,start=e.start,end=e.end)

    def parse_block(self):
        st=self.expect_punc('{')
        old_strict=self.strict
        body=self.parse_statement_list(stop_rbrace=True)
        en=self.expect_punc('}')
        self.strict=old_strict
        return N('block',body,start=st.start,end=en.end)

    def parse_var_decl_stmt(self):
        kind=self.advance().val
        st=self.i
        decls=self.parse_var_declarators(kind)
        self.consume_semi()
        start=decls[0][2] if decls else 0
        return N('vardecl',kind,decls)

    def parse_var_declarators(self,kind,in_for=False):
        decls=[]
        while True:
            start=self.tok.start
            pat=self.parse_binding_pattern()
            init=None
            if self.is_punc('='):
                self.advance(); init=self.parse_assignment()
            elif kind=='const' and not in_for:
                self.unexpected(msg="Unexpected token } ")
