    # ---------- patterns ----------
    def parse_binding_pattern(self):
        t=self.tok
        if t.kind=='name':
            if t.val in RESERVED_ALWAYS or (self.strict and t.val in RESERVED_STRICT) or t.val in ('true','false','null'):
                self.unexpected()
            if self.strict and t.val in ('eval','arguments'):
                self.compile_error("Unexpected token eval" if False else f"SyntaxError: Unexpected eval or arguments in strict mode",t)
            self.advance(); return N('idpat',t.val,start=t.start,end=t.end)
        if self.is_punc('{'):
            return self.parse_object_pattern()
        if self.is_punc('['):
            return self.parse_array_pattern()
        self.unexpected()

    def parse_object_pattern(self):
        st=self.expect_punc('{'); props=[]
        while not self.is_punc('}'):
            if self.eat_punc('...'):
                target=self.parse_binding_pattern(); props.append(N('rest',target)); break
            # key
            kt=self.tok; computed=False; key=None
            if self.is_punc('['):
                self.advance(); key=self.parse_assignment(); self.expect_punc(']'); computed=True
            elif kt.kind=='name':
                key=kt.val; self.advance()
            elif kt.kind=='str':
                key=kt.val; self.advance()
            elif kt.kind in ('num','bigint'):
                self.check_legacy_number(kt); key=kt.raw or str(kt.val); self.advance()
            else:
                self.unexpected()
            if self.eat_punc(':'):
                pat=self.parse_binding_pattern()
            else:
                if computed: self.unexpected()
                pat=N('idpat',key,start=kt.start,end=kt.end)
            if self.eat_punc('='):
                d=self.parse_assignment(); pat=N('assignpat',pat,d)
            props.append(N('prop',key,pat,computed))
            if not self.eat_punc(','): break
            if self.is_punc('}'): break
        en=self.expect_punc('}')
        return N('objpat',props,start=st.start,end=en.end)
    def parse_array_pattern(self):
        st=self.expect_punc('['); elems=[]
        while not self.is_punc(']'):
            if self.is_punc(','):
                elems.append(None); self.advance(); continue
            if self.eat_punc('...'):
                elems.append(N('rest',self.parse_binding_pattern())); break
            pat=self.parse_binding_pattern()
            if self.eat_punc('='):
                pat=N('assignpat',pat,self.parse_assignment())
            elems.append(pat)
            if not self.eat_punc(','): break
        en=self.expect_punc(']')
        return N('arrpat',elems,start=st.start,end=en.end)

    def expr_to_pattern(self,e):
        if e is None: return e
        if e.kind=='id': return N('idpat',e.a,start=e.start,end=e.end)
        if e.kind=='member': return e
        if e.kind=='arrlit':
            elems=[]
            for el in e.a:
                if el is None: elems.append(None)
                elif el.kind=='spread': elems.append(N('rest',self.expr_to_pattern(el.a)))
                elif el.kind=='assign': elems.append(N('assignpat',self.expr_to_pattern(el.a),el.b))
                else: elems.append(self.expr_to_pattern(el))
            return N('arrpat',elems,start=e.start,end=e.end)
        if e.kind=='objlit':
            props=[]
            for pr in e.a:
                if pr.kind=='spread': props.append(N('rest',self.expr_to_pattern(pr.a))); continue
                # prop node: a=key, b=value, c=computed, d=kind
                v=pr.b
                if v.kind=='assign':
                    pat=N('assignpat',self.expr_to_pattern(v.a),v.b)
                else:
                    pat=self.expr_to_pattern(v)
                props.append(N('prop',pr.a,pat,pr.c))
            return N('objpat',props,start=e.start,end=e.end)
        if e.kind=='assign':
            return N('assignpat',self.expr_to_pattern(e.a),e.b)
        self.unexpected(msg="Invalid left-hand side in assignment ")
    def is_valid_lhs(self,e):
        return e is not None and e.kind in ('id','member','chain')

    # ---------- functions/classes ----------
    def parse_function_decl(self,async_=False,generator=None):
        f=self.parse_function(async_=async_,generator=generator,is_decl=True)
        return N('funcdecl',f,start=f.start,end=f.end)
    def parse_function(self,async_=False,generator=None,is_decl=False,is_method=False,method_kind='method',name_override=None,start_override=None):
        start_tok=self.tok
        if async_:
            # current may be 'async' name
            if self.is_name('async'): self.advance()
        if self.is_name('function'):
            ft=self.advance(); start=start_override if start_override is not None else ft.start
        else:
            start=start_override if start_override is not None else start_tok.start
        gen=False
        if generator is not None: gen=generator
        if self.is_punc('*'):
            self.advance(); gen=True
        name=name_override
        if name is None:
            if self.tok.kind=='name' and self.tok.val not in RESERVED_ALWAYS:
                name=self.tok.val; self.advance()
            elif is_decl:
                # default export etc not supported
                self.unexpected()
            else:
                name=''
        params,rest = self.parse_params()
        self._check_duplicate_params(params,async_,gen)
        body,ben = self.parse_function_body(async_,gen)
        fn=N('func',name,params,body,{'async':async_,'gen':gen,'rest':rest,'method_kind':method_kind},start=start,end=ben)
        return fn
    def parse_params(self):
        self.expect_punc('(')
        params=[]; rest=False
        if self.is_punc(')'):
            self.advance(); return params,rest
        while True:
            if self.eat_punc('...'):
                pat=self.parse_binding_pattern(); params.append(N('rest',pat)); rest=True
                if self.is_punc('='): self.unexpected()
                break
            pat=self.parse_binding_pattern()
            if self.eat_punc('='):
                pat=N('assignpat',pat,self.parse_assignment())
            params.append(pat)
            if not self.eat_punc(','): break
            if self.is_punc(')'): break
