from js_lexer import Lexer, Tok, JSSyntaxErrorEx, KEYWORDS

RESERVED_STRICT={'implements','package','protected','interface','private','public','static','let'}
RESERVED_ALWAYS={'break','case','catch','class','const','continue','debugger','default','delete','do','else','export','extends','finally','for','function','if','import','in','instanceof','new','return','super','switch','this','throw','try','typeof','var','void','while','with','yield','enum'}

class N:
    __slots__=('kind','a','b','c','d','start','end')
    def __init__(self,kind,a=None,b=None,c=None,d=None,start=0,end=0):
        self.kind=kind; self.a=a; self.b=b; self.c=c; self.d=d; self.start=start; self.end=end
    def __repr__(self):
        return f"N({self.kind},{self.a!r},{self.b!r},{self.c!r})"

BIN_PREC={
 ',':0,
 # assignment handled separately
 '??':3,
 '||':4,
 '&&':5,
 '|':6,
 '^':7,
 '&':8,
 '==':9,'!=':9,'===':9,'!==':9,
 '<':10,'<=':10,'>':10,'>=':10,'in':10,'instanceof':10,
 '<<':11,'>>':11,'>>>':11,
 '+':12,'-':12,
 '*':13,'/':13,'%':13,
 '**':14,
}
ASSIGN_OPS={'=','+=','-=','*=','/=','%=','**=','<<=','>>=','>>>=','&=','|=','^=','&&=','||=','??='}

class Parser:
    def __init__(self,src,eval_direct=False,allow_return_outside=False):
        self.src=src
        self.lx=Lexer(src)
        self.toks=self.lx.tokenize()
        self.i=0
        self.strict=False
        self.in_function=0
        self.in_generator=False
        self.in_async=False
        self.allow_yield=False
        self.allow_await=False
        self.allow_return=allow_return_outside
        self.in_loop=0
        self.in_switch=0
        self.labels=[]
        self.eval_direct=eval_direct
        self.super_context=None  # 'method' if super property allowed, 'derived_ctor' etc (loosely)

    # token helpers
    @property
    def tok(self): return self.toks[self.i]
    def peek(self,n=1):
        j=self.i+n
        return self.toks[j] if j < len(self.toks) else self.toks[-1]
    def at_eof(self): return self.tok.kind=='eof'
    def is_punc(self,v,t=None):
        t=t or self.tok
        return t.kind=='punc' and t.val==v
    def is_name(self,v,t=None):
        t=t or self.tok
        return t.kind=='name' and t.val==v
    def advance(self):
        t=self.tok
        if t.kind!='eof': self.i+=1
        return t
    def eat_punc(self,v):
        if self.is_punc(v): self.advance(); return True
        return False
    def eat_name(self,v):
        if self.is_name(v): self.advance(); return True
        return False
    def expect_punc(self,v):
        if not self.is_punc(v): self.unexpected()
        return self.advance()
    def save(self):
        return (self.i,self.strict,self.in_function,self.in_generator,self.in_async,self.allow_yield,self.allow_await,self.allow_return,self.in_loop,self.in_switch,list(self.labels),self.super_context)
    def restore(self,s):
        (self.i,self.strict,self.in_function,self.in_generator,self.in_async,self.allow_yield,self.allow_await,self.allow_return,self.in_loop,self.in_switch,self.labels,self.super_context)=s

    # errors
    def tok_display(self,t):
        if t.kind=='eof': return '}'
        # EOF in goja parser messages often shows as } because expected closing brace of wrapper.
        if t.kind=='punc': return t.val
        if t.kind=='name': return t.val
        if t.kind=='illegal': return 'ILLEGAL'
        if t.kind=='str': return 'string'
        if t.kind in ('num','bigint'): return 'number'
        return str(t.val)
    def unexpected(self,t=None,category='parser',msg=None):
        t=t or self.tok
        if msg is None:
            if t.kind=='illegal':
                if getattr(t,'flags',None)=='missing_slash':
                    msg="Invalid regular expression: missing /"
                else:
                    msg="Unexpected token ILLEGAL "
            elif t.kind=='name':
                if t.val in KEYWORDS and t.val not in ('this','super'):
                    msg=f"Unexpected token {t.val} "
                else:
                    msg="Unexpected identifier"
            elif t.kind in ('num','bigint'):
                msg="Unexpected number"
            elif t.kind=='str':
                msg="Unexpected string"
            elif t.kind=='eof':
                msg="Unexpected token } "
            elif t.kind=='regex':
                msg="Unexpected token /"
            else:
                msg=f"Unexpected token {self.tok_display(t)} "
        raise JSSyntaxErrorEx(msg,t.start,category,line=t.line,col=t.col)
    def compile_error(self,msg,t=None):
        t=t or self.tok
        raise JSSyntaxErrorEx(msg,t.start,'compile',line=t.line,col=t.col)
    def check_legacy_number(self,t):
        if t.kind in ('num','bigint') and getattr(t,'flags',None):
            if t.flags=='legacy_octal':
                if self.strict:
                    raise JSSyntaxErrorEx("Octal literals are not allowed in strict mode",t.start,'compile',line=t.line,col=t.col)
            elif t.flags=='legacy_nonoctal':
                # goja: token ILLEGAL for 08/09 in parse phase
                raise JSSyntaxErrorEx("Unexpected token ILLEGAL ",t.start,'parser',line=t.line,col=t.col)

    # semicolons / ASI
    def consume_semi(self):
        if self.is_punc(';'): self.advance(); return
        if self.at_eof() or self.is_punc('}') or self.tok.nl: return
        self.unexpected()
    def is_terminal(self):
        return self.at_eof() or self.is_punc('}') or self.tok.nl or self.is_punc(';')

    # ---------- program / statements ----------
    def parse_program(self):
        start=self.tok.start
        body=[]
        # directive prologue handled for strict setting during parse of statements:
        body=self.parse_statement_list(top=True)
        if not self.at_eof():
            self.unexpected()
        return N('program',body,start=start,end=self.toks[-1].end)

    def parse_statement_list(self,top=False,stop_rbrace=False):
        stmts=[]
        seen_directive=True
        while not self.at_eof():
            if stop_rbrace and self.is_punc('}'): break
            st=self.parse_statement()
            if st is None:
                continue
            # directive handling: a leading string literal expression statement
            if seen_directive and st.kind=='exprstmt' and st.a.kind=='literal' and isinstance(st.a.a,str) and st.a.b=='str':
                if st.a.a=='use strict':
                    self.strict=True
                stmts.append(st); continue
            seen_directive=False
            stmts.append(st)
        return stmts

    def parse_single_expression_program(self):
        # used for precheck snippets? (not main path)
        e=self.parse_expression()
        return e

    def parse_statement(self):
        t=self.tok
        if t.kind=='punc':
            if t.val==';': self.advance(); return N('empty',start=t.start,end=t.end)
            if t.val=='{': return self.parse_block()
        if t.kind=='name':
            v=t.val
            if v=='var' or v=='const': return self.parse_var_decl_stmt()
            if v=='let':
                # let declaration if followed by identifier, [, { ; in sloppy let can be identifier.
                nt=self.peek()
                if nt.kind=='name' and nt.val not in RESERVED_ALWAYS or (nt.kind=='punc' and nt.val in ('[','{')):
                    return self.parse_var_decl_stmt()
                if self.strict and nt.kind=='name':
                    return self.parse_var_decl_stmt()
                # identifier expression
            if v=='function': return self.parse_function_decl()
            if v=='class': return self.parse_class_decl()
            if v=='if': return self.parse_if()
            if v=='while': return self.parse_while()
            if v=='do': return self.parse_do()
            if v=='for': return self.parse_for()
            if v=='switch': return self.parse_switch()
            if v=='try': return self.parse_try()
            if v=='throw':
                self.advance()
                if self.tok.nl: self.unexpected(msg="Unexpected token } ")
                e=self.parse_expression(); self.consume_semi(); return N('throw',e,start=t.start,end=e.end)
            if v=='return':
                if not self.allow_return and self.in_function==0:
                    # Goja parser says Unexpected token return in reducer wrapper because return is consumed by wrapper's own return; in general scripts it's compile-ish. Keep parser message.
                    self.unexpected(msg="Unexpected token return ")
                self.advance()
                if self.is_terminal():
                    if self.is_punc(';'): self.advance()
                    return N('return',None,start=t.start,end=t.end)
                e=self.parse_expression(); self.consume_semi(); return N('return',e,start=t.start,end=e.end)
            if v=='break' or v=='continue':
                self.advance()
                label=None
                if not self.is_terminal() and self.tok.kind=='name':
                    label=self.tok.val; self.advance()
                self.consume_semi()
                return N(v,label,start=t.start,end=t.end)
            if v=='debugger':
                self.advance(); self.consume_semi(); return N('debugger',start=t.start,end=t.end)
            if v=='with':
                # In strict mode error; goja reports Unexpected token with in wrapping contexts.
                self.unexpected(msg="Unexpected token with ")
            if v=='async':
                # async function declaration
                if self.is_name('function',self.peek()) and not self.peek().nl:
                    return self.parse_function_decl(async_=True)
            if v=='import':
                if self.is_punc('(',self.peek()) or self.is_punc('.',self.peek()):
                    pass # expression import()
                else:
                    self.unexpected(msg="Unexpected token import ")
            if v=='export':
                self.unexpected(msg="Unexpected token export ")
            # labelled statement?
            if self.is_punc(':',self.peek()):
                if v in RESERVED_ALWAYS or (self.strict and v in RESERVED_STRICT):
                    self.unexpected()
                self.advance(); self.advance()
                body=self.parse_statement()
                return N('labeled',v,body,start=t.start,end=body.end if body else t.end)
        # expression statement; { begins block handled; function/class handled
        e=self.parse_expression()
        self.consume_semi()
        return N('exprstmt',e,start=e.start,end=e.end)

    def parse_block(self):
        st=self.expect_punc('{')
        old_strict=self.strict
        body=self.parse_statement_list(stop_rbrace=True)
        en=self.expect_punc('}')
        self.strict=old_strict
        return N('block',body,start=st.start,end=en.end)

    def parse_var_decl_stmt(self):
        kind=self.advance().val
        st=self.i
        decls=self.parse_var_declarators(kind)
        self.consume_semi()
        start=decls[0][2] if decls else 0
        return N('vardecl',kind,decls)

    def parse_var_declarators(self,kind,in_for=False):
        decls=[]
        while True:
            start=self.tok.start
            pat=self.parse_binding_pattern()
            init=None
            if self.is_punc('='):
                self.advance(); init=self.parse_assignment()
            elif kind=='const' and not in_for:
                self.unexpected(msg="Unexpected token } ")
            decls.append((pat,init,start))
            if not self.eat_punc(','): break
        return decls

    def parse_if(self):
        st=self.advance(); self.expect_punc('('); cond=self.parse_expression(); self.expect_punc(')')
        then=self.parse_statement()
        els=None
        if self.eat_name('else'):
            els=self.parse_statement()
        return N('if',cond,then,els,start=st.start)
    def parse_while(self):
        st=self.advance(); self.expect_punc('('); cond=self.parse_expression(); self.expect_punc(')')
        self.in_loop+=1; body=self.parse_statement(); self.in_loop-=1
        return N('while',cond,body,start=st.start)
    def parse_do(self):
        st=self.advance(); self.in_loop+=1; body=self.parse_statement(); self.in_loop-=1
        if not self.eat_name('while'): self.unexpected()
        self.expect_punc('('); cond=self.parse_expression(); self.expect_punc(')')
        if self.is_punc(';'): self.advance()
        return N('dowhile',cond,body,start=st.start)
    def parse_for(self):
        st=self.advance()
        await_=False
        if self.eat_name('await'):
            await_=True
        self.expect_punc('(')
        init=None
        if not self.is_punc(';'):
            if self.is_name('var') or self.is_name('const') or (self.is_name('let') and self._let_decl_ahead()):
                kind=self.advance().val
                # check for-in/of single declarator
                save=self.save()
                pat_start=self.tok.start
                pat=self.parse_binding_pattern()
                if self.is_name('in') or self.is_name('of'):
                    op=self.advance().val
                    right=self.parse_expression() if op=='in' else self.parse_assignment()
                    self.expect_punc(')')
                    self.in_loop+=1; body=self.parse_statement(); self.in_loop-=1
                    left=N('vardecl',kind,[(pat,None,pat_start)])
                    return N('forin' if op=='in' else 'forof',left,right,body,await_,start=st.start)
                initv=None
                decls=[]
                if self.is_punc('='):
                    self.advance(); initv=self.parse_assignment(in_ok=False)
                decls.append((pat,initv,pat_start))
                while self.eat_punc(','):
                    ps=self.tok.start; p2=self.parse_binding_pattern(); iv=None
                    if self.is_punc('='): self.advance(); iv=self.parse_assignment(in_ok=False)
                    decls.append((p2,iv,ps))
                init=N('vardecl',kind,decls)
            else:
                # expression, but 'in' not allowed in init
                e=self.parse_expression(in_ok=False)
                if self.is_name('in') or self.is_name('of'):
                    op=self.advance().val
                    left=self.expr_to_pattern(e) if op=='of' else e
                    right=self.parse_expression() if op=='in' else self.parse_assignment()
                    self.expect_punc(')')
                    self.in_loop+=1; body=self.parse_statement(); self.in_loop-=1
                    return N('forin' if op=='in' else 'forof',left,right,body,await_,start=st.start)
                init=e
        self.expect_punc(';')
        test=None
        if not self.is_punc(';'): test=self.parse_expression()
        self.expect_punc(';')
        upd=None
        if not self.is_punc(')'): upd=self.parse_expression()
        self.expect_punc(')')
        self.in_loop+=1; body=self.parse_statement(); self.in_loop-=1
        return N('for',init,test,upd,body,start=st.start)
    def _let_decl_ahead(self):
        nt=self.peek()
        return (nt.kind=='name') or (nt.kind=='punc' and nt.val in ('[','{'))
    def parse_switch(self):
        st=self.advance(); self.expect_punc('('); e=self.parse_expression(); self.expect_punc(')'); self.expect_punc('{')
        cases=[]; self.in_switch+=1
        while not self.is_punc('}'):
            if self.at_eof(): self.unexpected()
            if self.eat_name('case'):
                ce=self.parse_expression(); self.expect_punc(':')
            elif self.eat_name('default'):
                ce=None; self.expect_punc(':')
            else:
                self.unexpected()
            body=[]
            while not self.is_punc('}') and not self.is_name('case') and not self.is_name('default'):
                s=self.parse_statement()
                if s: body.append(s)
            cases.append((ce,body))
        self.in_switch-=1; self.expect_punc('}')
        return N('switch',e,cases,start=st.start)
    def parse_try(self):
        st=self.advance(); block=self.parse_block()
        catch=None; fin=None
        if self.eat_name('catch'):
            param=None
            if self.eat_punc('('):
                param=self.parse_binding_pattern(); self.expect_punc(')')
            cblock=self.parse_block(); catch=(param,cblock)
        if self.eat_name('finally'):
            fin=self.parse_block()
        if catch is None and fin is None: self.unexpected()
        return N('try',block,catch,fin,start=st.start)
