    def parse_unary_rhs_for_pow(self,right):
        return right

    def parse_unary(self):
        t=self.tok
        if t.kind=='punc' and t.val in ('+','-','!','~','++','--'):
            self.advance()
            arg=self.parse_unary()
            if t.val in ('++','--'):
                if not self.is_valid_lhs(arg):
                    self.unexpected(msg="Invalid left-hand side in assignment ")
                return N('update',t.val,arg,True,start=t.start,end=arg.end)
            return N('unary',t.val,arg,start=t.start,end=arg.end)
        if t.kind=='name' and t.val in ('typeof','void','delete'):
            self.advance()
            arg=self.parse_unary()
            if t.val=='delete' and arg.kind=='id':
                # strict compile error
                raise JSSyntaxErrorEx("Delete of an unqualified identifier in strict mode",arg.start,'compile')
            return N('unary',t.val,arg,start=t.start,end=arg.end)
        if t.kind=='name' and t.val=='await' and self.allow_await:
            self.advance(); arg=self.parse_unary(); return N('await',arg,start=t.start,end=arg.end)
        if t.kind=='name' and t.val=='await' and self.in_function==0 and False:
            pass
        e=self.parse_postfix()
        return e

    def parse_postfix(self):
        e=self.parse_lefthand()
        if not self.tok.nl and self.tok.kind=='punc' and self.tok.val in ('++','--'):
            op=self.advance()
            if not self.is_valid_lhs(e):
                self.unexpected(msg="Invalid left-hand side in assignment ")
            return N('update',op.val,e,False,start=e.start,end=op.end)
        return e
