    def parse_lefthand(self):
        # new / member / call / optional chain
        if self.is_name('new'):
            nt=self.advance()
            if self.is_punc('.'):
                self.advance()
                if not self.is_name('target'): self.unexpected()
                self.advance(); e=N('newtarget',start=nt.start)
                return self.parse_call_member_tail(e,allow_call=False)
            callee=self.parse_lefthand()
            args=[]
            if self.is_punc('('):
                args=self.parse_args()
            e=N('new',callee,args,start=nt.start,end=callee.end)
            return self.parse_call_member_tail(e)
        if self.is_name('super'):
            st=self.advance()
            if self.is_punc('('):
                args=self.parse_args(); e=N('supercall',args,start=st.start)
                return self.parse_call_member_tail(e,allow_call=False)
            # super.prop handled as primary object for member
            e=N('super',start=st.start,end=st.end)
            return self.parse_call_member_tail(e)
        if self.is_name('import'):
            st=self.tok
            if self.is_punc('(',self.peek()):
                self.advance(); args=self.parse_args(); e=N('importcall',args,start=st.start); return self.parse_call_member_tail(e)
            if self.is_punc('.',self.peek()):
                self.advance(); self.advance();
                if not self.is_name('meta'): self.unexpected()
                self.advance(); e=N('importmeta',start=st.start); return self.parse_call_member_tail(e)
        e=self.parse_primary()
        return self.parse_call_member_tail(e)

    def parse_args(self):
        self.expect_punc('('); args=[]
        if self.is_punc(')'):
            self.advance(); return args
        while True:
            if self.eat_punc('...'):
                args.append(N('spread',self.parse_assignment()))
            else:
                args.append(self.parse_assignment())
            if not self.eat_punc(','): break
            if self.is_punc(')'): break
        self.expect_punc(')')
        return args

    def parse_call_member_tail(self,e,allow_call=True):
        # Build either plain member/call nodes or a 'chain' node when ?. appears.
        chain_ops=None
        base=e
        def ensure_chain():
            nonlocal chain_ops,e
            if chain_ops is None:
                root = e
                chain_ops=[]
                return root
            return base
        # We reconstruct chain by collecting ops from a rootprimary; easier: if we encounter ?. we convert current e by unwrapping member/call nodes is hard.
        # Instead handle chain conversion by storing ops as we go in a separate list when the caller is parse_lefthand primary path.
        # This method is called with a single node and then loops, so we can keep ops list from the start.
        ops=[]
        root=e
        has_optional=False
        cur=e  # non-chain current
        while True:
            if self.is_punc('.'):
                self.advance()
                if self.is_punc('#'):
                    self.advance(); kt=self.tok
                    if kt.kind!='name': self.unexpected()
                    self.advance(); prop='#'+kt.val; computed=False
                else:
                    kt=self.tok
                    if kt.kind!='name':
                        self.unexpected()
                    self.advance(); prop=kt.val; computed=False
                if has_optional:
                    ops.append(('member',prop,computed,False))
                else:
                    cur=N('member',cur,prop,computed,start=cur.start,end=kt.end)
                continue
            if self.is_punc('['):
                self.advance(); prop=self.parse_expression(); en=self.expect_punc(']')
                if has_optional:
                    ops.append(('member',prop,True,False))
                else:
                    cur=N('member',cur,prop,True,start=cur.start,end=en.end)
                continue
            if allow_call and self.is_punc('('):
                args=self.parse_args()
                if has_optional:
                    ops.append(('call',args,False))
                else:
                    cur=N('call',cur,args,start=cur.start)
                continue
            if self.is_punc('?.'):
                # convert cur (built so far) into chain root
                if not has_optional:
                    has_optional=True; root=cur; ops=[]
                self.advance()
                if self.is_punc('('):
                    args=self.parse_args(); ops.append(('call',args,True)); continue
                if self.is_punc('['):
                    self.advance(); prop=self.parse_expression(); self.expect_punc(']'); ops.append(('member',prop,True,True)); continue
