    def find_binding(self,env,name):
        e=env
        while e is not None:
            if name in e.vars:
                return (e,e.vars[name])
            if isinstance(e,GlobalEnv):
                d=R.get_own_desc(self.vm,e.global_obj,name)
                if d is not None:
                    return (e,('global',d))
            e=e.outer
