    # ---------- expression evaluation ----------
    def eval_expr(self,node,env):
        vm=self.vm
        k=node.kind
        if k=='literal':
            if node.b=='null': return NULL
            if node.b=='bigint': return R.BigInt(node.a)
            if node.b=='regex':
                return make_regex(vm,node.a[0],node.a[1])
            if node.b=='num': return R.make_number(node.a)
            return node.a
        if k=='id':
            name=node.a
            if name=='undefined':
                # identifier resolution: global undefined property, but may be shadowed by local binding
                if self.find_binding(env,name) is not None:
                    return self.get_name(env,name)
                return UNDEFINED
            return self.get_name(env,name)
        if k=='this': return self.get_this(env)
        if k=='arrlit': return self.eval_array_literal(node,env)
        if k=='objlit': return self.eval_object_literal(node,env)
        if k=='func': return self.create_function(node,env)
        if k=='arrow': return self.create_function(node,env)
        if k=='class': return self.eval_class(node,env)
        if k=='template':
            return self.eval_template(node,env,tagged=False)
        if k=='tagged':
            raise Exception('tagged handled in call tail')
        if k=='member': return self.eval_member(node,env)
        if k=='chain': return self.eval_chain(node,env)
        if k=='call': return self.eval_call(node,env)
        if k=='new': return self.eval_new(node,env)
        if k=='seq':
            r=UNDEFINED
            for e in node.a: r=self.eval_expr(e,env)
            return r
        if k=='assign': return self.eval_assign(node,env)
        if k=='cond':
            return self.eval_expr(node.b,env) if truthy(self.eval_expr(node.a,env)) else self.eval_expr(node.c,env)
        if k=='unary': return self.eval_unary(node,env)
        if k=='update': return self.eval_update(node,env)
        if k=='binary': return self.eval_binary(node,env)
        if k=='logical': return self.eval_logical(node,env)
        if k=='await':
            v=self.eval_expr(node.a,env)
            return vm.exec_await(v)
        if k=='yield':
            v=self.eval_expr(node.a,env) if node.a is not None else UNDEFINED
            return vm.exec_yield(v,node.b,env,self)
        if k=='newtarget':
            return self.new_target_stack[-1] if self.new_target_stack else UNDEFINED
        if k=='supercall':
            return self.eval_super_call(node,env)
        if k=='super':
            # alone super is invalid; member handles it
            vm.type_error("super is not allowed here")
        if k=='importcall':
            vm.type_error("import() is not supported")
        if k=='importmeta':
            return vm.new_object()
        if k=='spread':
            # only valid in literals/args; evaluate inner
            return self.eval_expr(node.a,env)
        raise Exception(f"unhandled expr {k}")

    def eval_array_literal(self,node,env):
        vm=self.vm; arr=vm.new_array(); idx=0
        for el in node.a:
            if el is None:
                idx+=1; arr.array_len=max(arr.array_len,idx); continue
            if el.kind=='spread':
                v=self.eval_expr(el.a,env)
                if isinstance(v,str):
                    for ch in self.string_codepoints(v):
                        arr.props[str(idx)]=R.Desc(ch); idx+=1
                else:
                    for x in R.iter_to_list(vm,v):
                        arr.props[str(idx)]=R.Desc(x); idx+=1
                arr.array_len=idx; continue
            v=self.eval_expr(el,env)
            arr.props[str(idx)]=R.Desc(v); idx+=1; arr.array_len=idx
        arr.array_len=max(arr.array_len,idx)
        return arr
    def string_codepoints(self,s):
        return list(s)

    def eval_object_literal(self,node,env):
        vm=self.vm; o=vm.new_object()
        for pr in node.a:
            if pr.kind=='spread':
                src=self.eval_expr(pr.a,env)
                if src is UNDEFINED or src is NULL: continue
                so=R.to_object(vm,src) if not isinstance(src,R.JSObject) else src
                for key in R.own_keys(vm,so):
                    d=R.get_own_desc(vm,so,key)
                    if d and d.enumerable:
                        o.props[key]=R.Desc(R.get(vm,so,key))
                continue
            key=self.compute_key(pr.a,env) if pr.c else self.key_from_node(pr.a)
            vnode=pr.b
            if pr.d in ('method','get','set'):
                fn=self.create_function(vnode,env,name_hint=key if isinstance(key,str) else '',method_kind=pr.d,home_object=o)
                if pr.d=='method':
                    o.props[key]=R.Desc(fn,True,True,True)
                else:
                    cur=o.props.get(key)
                    if cur and cur.kind=='accessor':
                        if pr.d=='get': cur.get=fn
                        else: cur.set=fn
                    else:
                        o.props[key]=R.Desc(kind='accessor',get=fn if pr.d=='get' else UNDEFINED,set=fn if pr.d=='set' else UNDEFINED,enumerable=True,configurable=True)
                continue
            # name inference
            if isinstance(vnode,N) and vnode.kind=='func' and not vnode.a:
                v=self.create_function(vnode,env,name_hint=key if isinstance(key,str) else '')
            elif isinstance(vnode,N) and vnode.kind=='arrow':
                v=self.create_function(vnode,env,name_hint=key if isinstance(key,str) else '')
            elif isinstance(vnode,N) and vnode.kind=='class' and not vnode.a:
                v=self.eval_class(vnode,env,name_hint=key if isinstance(key,str) else '')
            elif isinstance(vnode,N) and vnode.kind=='assign' and pr.d=='init' and not pr.c:
                # shorthand with default (cover) — only valid as actual object literal if it's {a=1} parsed as assign shorthand by our parser: JS would syntax error outside destructuring.
                # Our object parser constructs prop value as assign(shorthand id, default) for {a=1}.  That is invalid in object literal context.
                # To match goja, treat as evaluating assignment (assigns default to a and uses value) — goja may accept? keep as assignment evaluation.
                v=self.eval_expr(vnode,env)
            else:
                v=self.eval_expr(vnode,env)
            if key=='__proto__' and not pr.c:
                if isinstance(v,R.JSObject) or v is NULL:
