    def eval_template(self,node,env,tagged=False,tag=None):
        parts=node.a; exprs=node.b
        if tagged:
            # build strings array with raw prop
            cooked=[p[0] if p[0] is not None else UNDEFINED for p in parts]
            arr=self.vm.new_array(cooked)
            rawarr=self.vm.new_array([p[1] for p in parts])
            arr.props['raw']=R.Desc(rawarr,False,False,False)
            # freeze both roughly (Object.freeze) later if needed
            vals=[self.eval_expr(e,env) for e in exprs]
            return (arr,vals)
        out=[]
        for idx,(cooked,raw) in enumerate(parts):
            if cooked is None:
                raise JSThrow(self.vm.make_error('SyntaxError','Invalid escape sequence in template literal'))
            out.append(cooked)
            if idx<len(exprs):
                out.append(R.to_string(self.vm,self.eval_expr(exprs[idx],env)))
        return ''.join(out)

    def eval_chain(self,node,env):
        cur=self.eval_expr(node.a,env)
        # If root was a member/call expression, `this` for subsequent call should be base of last member op. Track "this" as we walk ops:
        this_for_call=UNDEFINED
        for op in node.b:
            if op[0]=='member':
                _,prop,computed,optional=op
                if optional and (cur is UNDEFINED or cur is NULL):
                    return UNDEFINED
                key=self.eval_expr(prop,env) if computed else prop
                if computed: key=R.to_property_key(self.vm,key)
                self.check_member_base(cur,key)
                prev=cur
                cur=R.get(self.vm,cur,key,receiver=cur)
                this_for_call=prev
            else: # call
                _,args,optional=op
                if optional and (cur is UNDEFINED or cur is NULL):
                    return UNDEFINED
                vals=self.eval_args(args,env)
                if not R.is_callable(cur):
                    self.call_type_error(cur,node)
                cur=R.call_value(self.vm,cur,this_for_call,vals)
                this_for_call=UNDEFINED
        return cur

    def eval_args(self,args,env):
        out=[]
        for a in args:
            if isinstance(a,N) and a.kind=='spread':
                v=self.eval_expr(a.a,env)
                if isinstance(v,str):
                    out.extend(list(v))
                else:
                    out.extend(R.iter_to_list(self.vm,v))
            else:
                out.append(self.eval_expr(a,env))
        return out

    def call_type_error(self,callee,node=None,callee_node=None):
        vm=self.vm
        # Attempt goja-like messages for common shapes; refinement based on original probes happens in tests.
        if callee_node is not None and callee_node.kind=='member':
            # e.g. x.foo()
            keyname=''
            if not callee_node.c: keyname=str(callee_node.b)
            vm.type_error(f"Object has no member '{keyname}'")
        if callee is UNDEFINED:
            vm.type_error("Value is not a function")
        vm.type_error("Value is not a function")

