        fn_node=node.a
        # Tagged template produced as 'call'?? templates are handled in call tail as node kind 'tagged' via parse_call_member_tail which returns N('tagged'...) as cur and then may wrap in call; handled below.
        if fn_node.kind=='tagged':
            return self.eval_tagged(fn_node,env)
        this=UNDEFINED
        if fn_node.kind=='member':
            if fn_node.a.kind=='super':
                base=self.get_super_base(env); key=self.eval_expr(fn_node.b,env) if fn_node.c else fn_node.b
                if fn_node.c: key=R.to_property_key(self.vm,key)
                recv=self.get_this(env); fn=R.get(self.vm,base,key,receiver=recv); this=recv
            else:
                base=self.eval_expr(fn_node.a,env)
                key=self.eval_expr(fn_node.b,env) if fn_node.c else fn_node.b
                if fn_node.c: key=R.to_property_key(self.vm,key)
                self.check_member_base(base,key)
                fn=R.get(self.vm,base,key,receiver=base); this=base
        elif fn_node.kind=='chain':
