    def eval_tagged(self,node,env):
        tag=self.eval_expr(node.a,env)
        arr,vals=self.eval_template(node.b,env,tagged=True)
        if not R.is_callable(tag): self.call_type_error(tag,node)
        this=UNDEFINED
        if node.a.kind=='member':
            # approximation (tag was re-evaluated above) — acceptable for common tag functions
            this=UNDEFINED
        return R.call_value(self.vm,tag,this,[arr]+vals)

    def eval_new(self,node,env):
        callee=self.eval_expr(node.a,env)
        args=self.eval_args(node.b,env) if node.b else []
        if not R.is_callable(callee):
            # messages like "x is not a constructor"
            name=''
            if node.a.kind=='id': name=node.a.a
            self.vm.type_error(f"{R.to_string(self.vm,callee) if False else name or 'Value'} is not a constructor")
        return R.construct_value(self.vm,callee,args,callee)

    def eval_super_call(self,node,env):
        # Only valid directly in derived class constructor; handled by class construction context stored on env chain
        args=self.eval_args(node.a,env)
        ctor_info=None
        e=env
        while e is not None:
            if getattr(e,'_ctor_info',None) is not None:
                ctor_info=e._ctor_info; break
            e=e.outer
        if ctor_info is None:
            self.vm.type_error("super() is only allowed in a derived class constructor")
        parent=ctor_info['extends']
        new_target=ctor_info['new_target']
        res=R.construct_value(self.vm,parent,args,new_target)
        # bind this
        holder=ctor_info['holder']
        holder.value=res; holder.initialized=True
        # install private + fields of current class (done by caller flag)
        ctor_info['super_done']=True
        self.init_class_instance(res,ctor_info['class_rec'],env)
        return res
