def to_int32(v):
    f=R.to_double(v) if not isinstance(v,R.BigInt) else float(v.v)
    if math.isnan(f) or math.isinf(f) or f==0: return 0
    n=math.trunc(abs(f)) % 4294967296
    if f<0: n=-n
    if n>=2147483648: n-=4294967296
    if n<-2147483648: n+=4294967296
    return int(n)
def to_uint32(v):
    f=R.to_double(v)
    if math.isnan(f) or math.isinf(f) or f==0: return 0
    return int(math.trunc(abs(f)) % 4294967296) if f>=0 else int((4294967296 - (math.trunc(abs(f)) % 4294967296)) % 4294967296)

