def _js_div(a,b):
    if b==0:
        if a==0 or math.isnan(a): return float('nan')
        return math.inf if math.copysign(1,a)*math.copysign(1,b)>0 else -math.inf
    return a/b
def _js_mod(a,b):
    if b==0 or math.isnan(a) or math.isnan(b) or math.isinf(a): return float('nan')
    if math.isinf(b): return a
    return math.fmod(a,b)
def _js_pow(a,b):
    try:
        r=math.pow(a,b)
        return r
    except OverflowError:
        return math.inf if not (a<0 and b==int(b) and int(b)%2) else -math.inf
    except ValueError:
        return float('nan')

def instanceof(vm,obj,ctor):
    if not isinstance(ctor,R.JSObject):
        vm.type_error("Right-hand side of 'instanceof' is not an object")
    m=R.get(vm,ctor,vm.well_known['hasInstance'])
    if m is not UNDEFINED and m is not NULL and R.is_callable(m):
        # Function.prototype[Symbol.hasInstance] is the default; still calling it works if implemented
        # Avoid infinite recursion if it's our default implementation: it is implemented to do ordinary check.
        return truthy(R.call_value(vm,m,ctor,[obj]))
    if not R.is_callable(ctor):
        vm.type_error("Right-hand side of 'instanceof' is not callable")
    if not isinstance(obj,R.JSObject): return False
    proto=R.get(vm,ctor,'prototype')
    if not isinstance(proto,R.JSObject):
        vm.type_error("Function has non-object prototype in instanceof check")
    cur=obj.proto
    while cur is not None:
        if cur is proto: return True
        cur=cur.proto if isinstance(cur,R.JSObject) else None
    return False

