import threading
class _GenState:
    pass

def _make_generator(vm,exe,fn,this,args):
    # Return a generator object that runs the function body in a cooperatively scheduled Python thread.
    proto=vm.protos.get('Object')
    gen=JSObject(proto,kind='generator',data={})
    state=_GenState(); state.started=False; state.done=False; state.thread=None; state.to_thread=threading.Event(); state.to_caller=threading.Event(); state.send_value=UNDEFINED; state.throw_value=None; state.yield_value=UNDEFINED; state.result=UNDEFINED; state.error=None; state.exe_ctx=None
    gen.data['state']=state; gen.data['fn']=fn
    def run_body():
        state.to_thread.wait(); state.to_thread.clear()
        if state.done: return
        try:
            fd=fn.data; node=fd.node; params=node.b if node.kind!='arrow' else node.a; body=node.c if node.kind!='arrow' else node.b
            fenv=exe.prepare_call_env(fd,this,args,params)
            exe.instantiate_block(body,fenv,func_top=True)
            result=None
            for st in body:
                r=exe.exec_stmt(st,fenv)
                if r is not None: result=r
            state.result=UNDEFINED
        except R.ReturnEx as e:
            state.result=e.value
        except BaseException as e:
            state.error=e
        state.done=True; state.to_caller.set()
    state.runner=run_body
    def gen_next(vm2,t,a,nt=None):
        return _gen_resume(vm2,t,a[0] if a else UNDEFINED,None)
    def gen_return(vm2,t,a,nt=None):
        st=t.data['state']; st.done=True; st.result=a[0] if a else UNDEFINED
        if st.thread and st.thread.is_alive():
            st.to_thread.set()
        res=vm2.new_object(); res.props['value']=Desc(st.result); res.props['done']=Desc(True); return res
    def gen_throw(vm2,t,a,nt=None):
        return _gen_resume(vm2,t,UNDEFINED,a[0] if a else UNDEFINED)
    gen.props['next']=Desc(vm.native_func('next',1,gen_next))
    gen.props['return']=Desc(vm.native_func('return',1,gen_return))
    gen.props['throw']=Desc(vm.native_func('throw',1,gen_throw))
    gen.props[vm.well_known['iterator']]=Desc(vm.native_func('[Symbol.iterator]',0,lambda vm2,t,a,nt=None: t))
