    except Exception: pass
    return gen

def _gen_resume(vm,gen,send,throwv):
    st=gen.data['state']
    res=vm.new_object()
    if st.done and st.thread is None or (st.done and not st.started and st.thread is None):
        pass
    if getattr(st,'finished',False):
        if throwv is not None:
            raise R.JSThrow(throwv)
        res.props['value']=Desc(st.result); res.props['done']=Desc(True); return res
    st.send_value=send; st.throw_value=throwv
    if not st.started:
        st.started=True; st.thread=threading.Thread(target=st.runner,daemon=True); st.thread.start()
    st.to_caller.clear(); st.to_thread.set()
    st.to_caller.wait()
    if st.error is not None:
        err=st.error; st.error=None; st.finished=True
        if isinstance(err,R.JSThrow): raise err
        raise err
    if st.done:
        st.finished=True
        res.props['value']=Desc(st.result); res.props['done']=Desc(True); return res
    res.props['value']=Desc(st.yield_value); res.props['done']=Desc(False); return res

