_orig_make_generator=_make_generator
def _make_generator_registered(vm,exe,fn,this,args):
    gen=_orig_make_generator(vm,exe,fn,this,args)
    if not hasattr(vm,'_gen_by_thread'): vm._gen_by_thread={}
    st=gen.data['state']
    orig_runner=st.runner
    def runner():
        vm._gen_by_thread[threading.get_ident()]=st
        try: orig_runner()
        finally: vm._gen_by_thread.pop(threading.get_ident(),None)
