def _go_time_string(dt_or_ms):
    # ms
    ms=dt_or_ms
    if isinstance(ms,float) and (math.isnan(ms) or math.isinf(ms)):
        # Goja exports invalid dates as zero time (?) approximate Go zero time string
        return '0001-01-01 00:00:00 +0000 UTC'
    import datetime
    try:
        dt=datetime.datetime.fromtimestamp(ms/1000.0)
        utc_dt=datetime.datetime.fromtimestamp(ms/1000.0, tz=datetime.timezone.utc)
    except Exception:
        return '0001-01-01 00:00:00 +0000 UTC'
    # Go Time.String in the location of the time value; Goja dates are in local time? Date object internally UTC instant exported as time in Local? new Date(0) displayed "+0000 UTC" in our UTC container.
    # Use the local dt with its tzname/offset.
    local=dt.astimezone()
    off=local.utcoffset(); tzname=local.tzname() or 'UTC'
    total=int(off.total_seconds()) if off else 0
    sign='+' if total>=0 else '-'; total=abs(total); oh=total//3600; om=(total%3600)//60
    frac=local.microsecond
    base=local.strftime('%Y-%m-%d %H:%M:%S')
    if frac:
        fs=('%06d'%frac).rstrip('0')
