        return PNode(BOOL,token=b'true' if v else b'false')
    if isinstance(v,R.BigInt):
        return PNode(NUM,token=str(v.v).encode())
    if R.is_num(v):
        f=R.to_double(v)
        if math.isnan(f): return PNode(SPECIAL,token=b'NaN')
        if math.isinf(f): return PNode(SPECIAL,token=(b'Infinity' if f>0 else b'-Infinity'))
        return PNode(NUM,token=R.number_to_string(v).encode())
    if isinstance(v,str):
        p=PNode(STR,token=quote_json_string(R.normalize_js_string(v)).encode('utf-8','surrogateescape'))
        p.string_value=v; p.top_raw=R.normalize_js_string(v).encode('utf-8','surrogateescape')
