        if v.kind=='function':
            raise _unsupported('func')
        if v.kind=='promise':
            raise _unsupported('ptr')
        if v.kind=='arraybuffer':
            raise _unsupported('struct')
        if v.kind in ('generator',):
            # Goja export of generator object is a plain object with no enumerable own props -> {}
            return PNode(OBJ,entries=[])
        if v.kind=='date':
            s=_go_time_string(v.data['ms'])
            return PNode(DATESTR,token=quote_json_string(s).encode())
        if v.kind in ('string_wrapper','number_wrapper','boolean_wrapper','bigint_wrapper','symbol_wrapper'):
            return _js_to_pnode(vm,v.data['value'],seen)
        if v.kind=='map' or v.kind=='set':
            return PNode(ARR,children=[])
        if v.kind=='typedarray':
            return PNode(ARR,children=[_js_to_pnode(vm,x,seen) for x in v.data['elems']])
        if v.kind=='proxy':
            t=v.data.get('target')
            if t is None: raise _unsupported('ptr')
            return _js_to_pnode(vm,t,seen)
        if id(v) in [id(x) for x in seen]:
            # mimic stack exhaustion as panic (rare)
            raise _unsupported('func')
        seen=seen+[v]
        if v.kind=='array' or v.kind=='arguments':
            ln=v.array_len if v.kind=='array' else int(R.to_double(R.to_number(vm,R.get(vm,v,'length')))) if R.get(vm,v,'length') is not UNDEFINED else 0
            children=[]
