                children.append(_js_to_pnode(vm,R.get(vm,v,str(i)),seen))
            return PNode(ARR,children=children)
        # generic object: own enumerable string keys
        entries=[]
        for k in R.own_keys(vm,v):
            if not isinstance(k,str): continue
            d=R.get_own_desc(vm,v,k)
            if not (d and d.enumerable): continue
            entries.append((quote_json_string(R.normalize_js_string(k)).encode('utf-8','surrogateescape'),_js_to_pnode(vm,R.get(vm,v,k),seen)))
