    use_toml=(not use_yaml) and (toml_flag or file_ext_toml)
    if use_yaml:
        from yamlx import yaml_stream_to_json_bytes
        data=yaml_stream_to_json_bytes(data, outw)
        if data is None:
            raise _SilentExit(1)
    elif use_toml:
        from tomlx import toml_to_json_bytes
        data=toml_to_json_bytes(data,outw)
        if data is None:
            raise _SilentExit(1)
    elif raw:
        # lines
        text=data
        if not text:
            nodes=[]
        else:
            # bufio ScanLines: split at \n, drop trailing \r before \n, final empty after trailing \n ignored
            parts=text.split(b'\n')
            if parts and parts[-1]==b'':
                parts=parts[:-1]
            nodes=[]
            for p in parts:
                if p.endswith(b'\r'): p=p[:-1]
