        while True:
            self.skip_blank_comments_and_markers()
            if self.i>=len(self.lines) or (self.i==len(self.lines)-1 and self.lines[self.i]==''):
                break
            node=self.parse_block(0)
            if node is not _EMPTY:
                docs.append(node)
            # after a document, loop handles '...'/'---'
        return docs
    def skip_blank_comments_and_markers(self):
        while self.i<len(self.lines):
            line=self.lines[self.i]
            s=line.strip()
            if s=='' or s.startswith('#') or s=='...' or s=='---':
                self.i+=1; continue
            if s.startswith('--- '):
                # inline content after --- is handled by rewriting current line
                content=line[line.index('---')+3:].lstrip()
                # Replace line with content at col 0 for parsing
                self.lines[self.i]=content
                return
            if s.startswith('... '):
