                        after=cline[1:].lstrip(' \t'); self.i+=1
                        val=self.parse_inline_or_nested(after,indent+1) if after else self.parse_block(indent+1)
                        if val is _EMPTY: val=None
                    else:
                        self.err("could not find expected ':'",self.i+1,indent+1)
                else:
                    self.i+=1
                    val=self.parse_block(indent+1)
                    if val is _EMPTY: val=None
                self._add_mapping_pair(mp,seen,key,val,key_line_no,indent+1)
                continue
            if not self.looks_like_mapping(stripped):
                break
            key_text, key, after, key_col = self.parse_mapping_key(stripped,indent)
            key_line_no=self.i+1
            self.i+=1
            if after is None:
                # ':' consumed but no inline (shouldn't happen)
                after=''
            if after=='' or after.startswith('#'):
                # nested block or null; anchors/tags might be in after (handled as value start below if non-empty)
                # If the *next* lines are more indented, parse nested; a sequence can be at same indent as key in YAML.
                nxt=self.peek_nonblank()
                if nxt is None:
                    val=None
                else:
                    nind=self.indent_of(self.lines[nxt]); nstr=self.lines[nxt].lstrip(' \t')
                    if nind>indent:
                        val=self.parse_block(indent+1)
                        if val is _EMPTY: val=None
                    elif nind==indent and (nstr=='-' or nstr.startswith('- ')):
                        val=self.parse_sequence(indent)
                    else:
                        val=None
            else:
                val=self.parse_inline_or_nested(after,indent+1)
            if isinstance(key,str) and key=='<<':
                self._merge_into(mp,seen,val)
            else:
                self._add_mapping_pair(mp,seen,key,val,key_line_no,key_col)
        return mp

    def _add_mapping_pair(self,mp,seen,key,val,line_no,col):
        ks=self.key_to_string(key)
        if ks in seen:
            self.err(f'mapping key "{ks}" already defined at [{seen[ks][0]}:{seen[ks][1]}]',line_no,col)
        seen[ks]=(line_no,col)
        mp.pairs.append((key,val))
    def _merge_into(self,mp,seen,val):
        sources=[]
        if isinstance(val,YMap): sources=[val]
        elif isinstance(val,list): sources=val
        for src in sources:
            if isinstance(src,YMap):
                for k,v in src.pairs:
                    ks=self.key_to_string(k)
                    if ks not in seen:
                        seen[ks]=(0,0); mp.pairs.append((k,v))
    def err(self,msg,line_no,col):
        raise YamlParseError(msg,line_no,col,self.raw_lines)

    def looks_like_mapping(self,s):
        # Find a colon followed by space/eol outside quotes and flow nesting (at depth 0). A plain scalar can't contain ": " or end colon in block contexts.
        in_s=False; in_d=False; depth=0; i=0
        while i<len(s):
            ch=s[i]
            if in_d:
                if ch=='\\': i+=2; continue
                if ch=='"': in_d=False
            elif in_s:
                if ch=="'":
                    if i+1<len(s) and s[i+1]=="'": i+=2; continue
                    in_s=False
            else:
                if ch=='"': in_d=True
                elif ch=="'": in_s=True
                elif ch in '[{': depth+=1
                elif ch in ']}': depth-=1
                elif ch=='#' and i>0 and s[i-1]==' ':
                    return False
                elif ch==':' and depth==0:
                    if i+1>=len(s) or s[i+1] in ' \t':
                        return i>0
            i+=1
        return False

    def parse_mapping_key(self,s,indent):
        # parse key up to ':'
        in_s=False; in_d=False; depth=0; i=0
        while i<len(s):
            ch=s[i]
            if in_d:
                if ch=='\\': i+=2; continue
                if ch=='"': in_d=False
            elif in_s:
                if ch=="'":
                    if i+1<len(s) and s[i+1]=="'": i+=2; continue
                    in_s=False
            else:
                if ch=='"': in_d=True
                elif ch=="'": in_s=True
                elif ch in '[{': depth+=1
                elif ch in ']}': depth-=1
                elif ch==':' and depth==0 and (i+1>=len(s) or s[i+1] in ' \t'):
                    break
            i+=1
        key_text=s[:i].rstrip()
        after=s[i+1:].lstrip(' \t') if i<len(s) else ''
        key=self.parse_flow_or_scalar_text(key_text,self.i+1,is_key=True)
        return key_text,key,after,indent+1

    def parse_inline_or_nested(self,content,content_indent,seq_indent=None):
        content=content.strip()
        # Strip comment for plain start positions handled inside scalar parsers where appropriate.
        # Anchors/tags prefix
        anchor, tag, rest = self.strip_anchor_tag(content)
        if rest:
            content=rest
            val=self.parse_inline_or_nested_inner(content,content_indent,tag)
            if anchor: self.anchors[anchor]=val
            return val
        # Only anchor/tag: value is following nested block
        val=self.parse_block(content_indent)
        if val is _EMPTY:
            # sequence at seq_indent (?) for sequence items "- &a" followed by nested at greater indent handled by parse_block; null fallback
            val=None
        if anchor: self.anchors[anchor]=val
        return val

    def parse_inline_or_nested_inner(self,content,content_indent,tag=None):
        content_stripped=content.strip()
        # Mapping starting on same line after "- key: value": treat as a mapping whose first key is at content_indent, subsequent keys expected at that indent.
        if self.looks_like_mapping(content_stripped) and not content_stripped.startswith(('{','[','"','\'')):
            # Create a pseudo-line and parse mapping by temporarily injecting it
            self.lines.insert(self.i,' '*content_indent+content_stripped)
            self.raw_lines=self.lines  # approximate (source lines for errors after this are shifted; acceptable)
            return self.parse_mapping(content_indent)
        # Block scalar indicators
        if re.fullmatch(r'[|>][+-]?\d*\s*(#.*)?',content_stripped) or re.fullmatch(r'[|>]\d*[+-]?\s*(#.*)?',content_stripped):
            return self.parse_block_scalar(content_stripped,content_indent)
        # Flow / quoted / scalar, possibly continuing over multiple physical lines (flow collections and quoted scalars)
        return self.parse_flow_or_scalar_text(content,self.i,tag=tag,multiline_indent=content_indent)

    def parse_block_scalar_or_flow(self,indent):
        line=self.lines[self.i]; content=line.lstrip(' \t')
        line_no=self.i+1
        self.i+=1
        anchor,tag,rest=self.strip_anchor_tag(content.strip())
        if rest:
            val=self.parse_inline_or_nested_inner(rest,indent,tag)
            if anchor: self.anchors[anchor]=val
            return val
        if anchor or tag:
            val=self.parse_block(indent)
            if anchor and val is not _EMPTY: self.anchors[anchor]=val
            return val
        if re.fullmatch(r'[|>][+-]?\d*\s*(#.*)?',content.strip()):
            return self.parse_block_scalar(content.strip(),indent)
        # plain/quoted/flow scalar possibly multi-line: we've consumed first line; fold continuation lines that are more indented (or blank) and aren't new structures at <=indent
        return self.parse_flow_or_scalar_text(content,line_no,multiline_indent=indent,first_line_consumed=True)

    def strip_anchor_tag(self,content):
        anchor=None; tag=None; s=content.strip()
        changed=True
        while changed:
            changed=False
            m=re.match(r'&([^\s\[\]{}#,]+)\s+',s)
            if m:
                anchor=m.group(1); s=s[m.end():]; changed=True; continue
            m=re.match(r'(&[^\s\[\]{}#,]+)$',s)
            if m:
                anchor=m.group(1)[1:]; s=''; changed=True; continue
            m=re.match(r'(!{1,2}[^\s]+)\s+',s)
            if m:
                tag=m.group(1); s=s[m.end():]; changed=True; continue
            m=re.match(r'(!{1,2}[^\s]+)$',s)
            if m:
                tag=m.group(1); s=''; changed=True; continue
        return anchor,tag,s.strip()

    def parse_block_scalar(self,indicator,parent_indent):
        style=indicator[0]
        rest=indicator[1:].split('#')[0].strip()
        chomp='clip'; explicit_indent=None
        for ch in rest:
            if ch=='+': chomp='keep'
            elif ch=='-': chomp='strip'
            elif ch.isdigit(): explicit_indent=int(ch)
        # gather lines
        start=self.i
        # determine indent from first nonblank
        j=start; detected=None
        while j<len(self.lines):
            if self.lines[j].strip()!='':
                detected=self.indent_of(self.lines[j]); break
            j+=1
        if detected is None:
            self.i=j; return ''
        content_indent=parent_indent+explicit_indent if explicit_indent else detected
        collected=[]
        i=start
        while i<len(self.lines):
            raw=self.lines[i]
            if raw.strip()=='':
                collected.append(''); i+=1; continue
            ind=self.indent_of(raw)
            if ind<content_indent:
                break
            collected.append(raw[content_indent:] if len(raw)>=content_indent else '')
            i+=1
        self.i=i
        # remove leading blank excess? block scalar starts after header; leading blank lines are part but simple: keep as newlines except one leading? Keep all.
        if style=='|':
            text='\n'.join(collected)
            if collected: text+='\n'
        else:
            text=_fold_lines(collected)
        if chomp=='strip':
            text=text.rstrip('\n')
        elif chomp=='clip':
            text=text.rstrip('\n')+('\n' if text else '')
        return text

    def parse_flow_or_scalar_text(self,text,line_no,is_key=False,tag=None,multiline_indent=None,first_line_consumed=False):
        # text is a chunk from one line; expand with continuation lines for flow collections/quoted strings.
        text=text.strip()
        # Comments: for plain scalars, " #" begins comment if not in quotes/flow.
        if text.startswith('*') and not is_key:
            m=re.match(r'\*([^\s,\]}#]+)',text)
            if m and (len(text)==m.end() or text[m.end()] in ' \t'):
                name=m.group(1)
                if name not in self.anchors:
                    # col: position of alias name in original line approximated: line_no is current line index sometimes; caller passes varying values. Search source line.
                    ln=line_no if isinstance(line_no,int) else self.i
                    # find in current source line
                    col=5
                    src=self.raw_lines[ln-1] if 1<=ln<=len(self.raw_lines) else ''
                    p=src.find('*'+name)
                    if p>=0: col=p+2
                    self.err(f'could not find alias "{name}"',ln,col)
                return self.anchors[name]
        if text.startswith(('[','{')):
            full=text
            # gather until balanced
            while not _flow_balanced(full):
                if self.i>=len(self.lines):
                    kind=']' if text.startswith('[') else '}'
                    token='sequence' if kind==']' else 'mapping'
                    src=self.raw_lines[line_no-1] if isinstance(line_no,int) and 1<=line_no<=len(self.raw_lines) else text
                    col=src.find(text[0])+1 if text and text[0] in src else 1
                    self.err(f"{token} end token '{kind}' not found",line_no if isinstance(line_no,int) else self.i,col)
                full+='\n'+self.lines[self.i]; self.i+=1
            fp=FlowParser(self,full,line_no if isinstance(line_no,int) else self.i)
            val=fp.parse_value()
            return val
        if text.startswith(('"','\'')):
            full=text
            while not _quoted_closed(full):
                if self.i>=len(self.lines):
                    break
                full+='\n'+self.lines[self.i]; self.i+=1
            val,rest=_parse_quoted(full)
            return val
        # plain scalar: may include continuation lines if first_line_consumed and following lines are more indented than multiline_indent and don't start a mapping/sequence at same level
        chunks=[_strip_plain_comment(text)]
        if multiline_indent is not None:
            while True:
                nxt=self.peek_nonblank()
                if nxt is None: break
                # preserve blank lines as paragraph separators: peek already skipped in index only - if there are blank lines, still continuation possible.
                nind=self.indent_of(self.lines[nxt])
                if nind<=multiline_indent: break
                # consume blanks up to nxt counting them
                blanks=0
                while self.i<nxt:
                    blanks+=1; self.i+=1
                cont=_strip_plain_comment(self.lines[self.i].strip()); self.i+=1
                chunks.append(('\n'*blanks)+cont if blanks else ' '+cont)
        joined=chunks[0]+''.join(chunks[1:])
        return self.scalar_value(joined.strip(),tag=tag)

    def scalar_value(self,s,tag=None):
        if tag in ('!!str','!<tag:yaml.org,2002:str>'):
            return s
        if s=='' or s in ('~','null','Null','NULL'):
            return None
        if s in ('true','True','TRUE'): return True
        if s in ('false','False','FALSE'): return False
        low=s.lower()
        if low in ('.inf','+.inf'): return YSpecial('.inf')
        if low=='-.inf': return YSpecial('-.inf')
        if low in ('.nan',): return YSpecial('.nan')
        # ints
        t=s.replace('_','')
        sign=1; body=t
        if body[:1] in ('+','-'):
            sign=-1 if body[0]=='-' else 1; body=body[1:]
        iv=None
        try:
            if re.fullmatch(r'0x[0-9a-fA-F]+',body): iv=int(body[2:],16)*sign
            elif re.fullmatch(r'0o[0-7]+',body): iv=int(body[2:],8)*sign
            elif re.fullmatch(r'0b[01]+',body): iv=int(body[2:],2)*sign
            elif re.fullmatch(r'0[0-7]+',body) and len(body)>1: iv=int(body,8)*sign
            elif re.fullmatch(r'0|[1-9][0-9]*',body): iv=int(body,10)*sign
        except Exception:
            iv=None
        if iv is not None:
            if -9223372036854775808<=iv<=18446744073709551615:
                return iv
            return s
        # floats: require dot
        if re.fullmatch(r'[+-]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][+-]?[0-9]+)?',s.replace('_','')) and '.' in s:
            try: return float(s.replace('_',''))
            except Exception: return s
        return s

    def key_to_string(self,key):
        if isinstance(key,str): return key
        if key is None: return 'null'
        if isinstance(key,bool): return 'true' if key else 'false'
        if isinstance(key,int): return str(key)
        if isinstance(key,float):
            return _yaml_float_to_json_token(key).rstrip('0').rstrip('.') if False else _scalar_float_str(key)
        if isinstance(key,YSpecial): return key.token
        return str(key)

class _Empty: pass
_EMPTY=_Empty()

def _fold_lines(collected):
    if not collected: return ''
    out=''
    for i,line in enumerate(collected):
        if i==0:
            out+=line
        else:
            if line=='':
                out+='\n'
            elif collected[i-1]=='':
                out+=line
            else:
                out+=' '+line
    if collected: out+='\n'
    return out

def _strip_plain_comment(s):
    # A # preceded by whitespace starts a comment (outside quotes - this is used for plain text chunks)
    idx=s.find(' #')
    if idx>=0: return s[:idx].rstrip()
    if s.startswith('#'): return ''
    return s

def _flow_balanced(s):
    depth=0; in_s=False; in_d=False; i=0
    while i<len(s):
        ch=s[i]
        if in_d:
            if ch=='\\': i+=2; continue
            if ch=='"': in_d=False
        elif in_s:
            if ch=="'":
                if i+1<len(s) and s[i+1]=="'": i+=2; continue
                in_s=False
        else:
            if ch=='"': in_d=True
            elif ch=="'": in_s=True
            elif ch in '[{': depth+=1
            elif ch in ']}': depth-=1
        i+=1
    return depth<=0 and not in_s and not in_d

def _quoted_closed(s):
    if not s: return True
    q=s[0]; i=1
    while i<len(s):
        ch=s[i]
        if q=='"' and ch=='\\': i+=2; continue
        if ch==q:
            if q=="'" and i+1<len(s) and s[i+1]=="'": i+=2; continue
            return True
        i+=1
    return False

def _parse_quoted(s):
    s=s.strip()
    q=s[0]
    if q=="'":
        out=''; i=1
        while i<len(s):
            if s[i]=="'":
                if i+1<len(s) and s[i+1]=="'": out+="'"; i+=2; continue
                return _fold_quoted(out), s[i+1:]
            out+=s[i]; i+=1
        return _fold_quoted(out),''
    out=''; i=1
    escapes={'0':'\0','a':'\a','b':'\b','t':'\t','\t':'\t','n':'\n','v':'\v','f':'\f','r':'\r','e':'\x1b',' ':' ','"':'"','/':'/','\\':'\\','N':'\x85','_':'\u00a0','L':'\u2028','P':'\u2029'}
    while i<len(s):
        ch=s[i]
        if ch=='"': return _fold_quoted(out),s[i+1:]
        if ch=='\\' and i+1<len(s):
            e=s[i+1]
            if e in escapes: out+=escapes[e]; i+=2; continue
            if e=='x': out+=chr(int(s[i+2:i+4],16)); i+=4; continue
            if e=='u': out+=chr(int(s[i+2:i+6],16)); i+=6; continue
            if e=='U': out+=chr(int(s[i+2:i+10],16)); i+=10; continue
            if e=='\n':
                i+=2
                while i<len(s) and s[i] in ' \t': i+=1
                continue
            out+=e; i+=2; continue
        out+=ch; i+=1
    return _fold_quoted(out),''
def _fold_quoted(s):
    # Fold line breaks in multi-line quoted scalars: single newline -> space, blank lines -> newline(s), trim leading spaces on continuation lines.
    if '\n' not in s: return s
    parts=s.split('\n')
    out=parts[0]
    for part in parts[1:]:
        if part.strip()=='':
            out+='\n'
        else:
            if out and not out.endswith('\n'): out+=' '
            out+=part.strip()
    return out

class FlowParser:
    def __init__(self,yp,text,line_no):
        self.yp=yp; self.s=text; self.i=0; self.line_no=line_no
    def skip(self):
        while self.i<len(self.s):
            if self.s[self.i] in ' \t\r\n': self.i+=1; continue
            if self.s[self.i]=='#':
                while self.i<len(self.s) and self.s[self.i]!='\n': self.i+=1
                continue
            break
    def peek(self): return self.s[self.i] if self.i<len(self.s) else ''
    def parse_value(self):
        self.skip()
        anchor,tag,rest=None,None,None
        # anchor/tag tokens in flow
        while True:
            if self.peek()=='&':
                self.i+=1; st=self.i
                while self.i<len(self.s) and self.s[self.i] not in ' \t\r\n,]}': self.i+=1
                anchor=self.s[st:self.i]; self.skip(); continue
            if self.peek()=='!':
                st=self.i
                while self.i<len(self.s) and self.s[self.i] not in ' \t\r\n': self.i+=1
                tag=self.s[st:self.i]; self.skip(); continue
            break
        v=self.parse_value_inner(tag)
        if anchor: self.yp.anchors[anchor]=v
        return v
    def parse_value_inner(self,tag=None):
        self.skip(); ch=self.peek()
        if ch=='[':
            self.i+=1; arr=[]
            while True:
                self.skip()
                if self.peek()==']': self.i+=1; return arr
                if self.i>=len(self.s): return arr
                arr.append(self.parse_value()); self.skip()
                if self.peek()==',': self.i+=1; continue
                if self.peek()==']': self.i+=1; return arr
                return arr
        if ch=='{':
            self.i+=1; mp=YMap(); seen={}
            while True:
                self.skip()
                if self.peek()=='}': self.i+=1; return mp
                if self.i>=len(self.s): return mp
                k=self.parse_value(); self.skip()
                if self.peek()==':': self.i+=1
                v=self.parse_value(); self.yp._add_mapping_pair(mp,seen,k,v,self.line_no,1)
                self.skip()
                if self.peek()==',': self.i+=1; continue
                if self.peek()=='}': self.i+=1; return mp
                return mp
        if ch in ('"',"'"):
            start=self.i
            # find closing
            sub=self.s[start:]
            val,rest=_parse_quoted(sub)
            self.i=start+(len(sub)-len(rest))
            return val
        if ch=='*':
            self.i+=1; st=self.i
            while self.i<len(self.s) and self.s[self.i] not in ' \t\r\n,]}#': self.i+=1
            name=self.s[st:self.i]
            if name not in self.yp.anchors:
                self.yp.err(f'could not find alias "{name}"',self.line_no,st)
            return self.yp.anchors[name]
        # plain scalar until , ] } or : followed by space in flow maps (colon handling by map loop)
        start=self.i; depth=0
        while self.i<len(self.s):
            c=self.s[self.i]
            if depth==0 and c in ',]}':
                break
            if depth==0 and c==':' and self.i+1<len(self.s) and self.s[self.i+1] in ' \t\r\n,]}':
                break
            if c in '[{': depth+=1
            elif c in ']}': depth-=1
            self.i+=1
        txt=self.s[start:self.i].strip()
        txt=_strip_plain_comment(txt)
        return self.yp.scalar_value(txt,tag=tag)

# ---------- YAML value -> JSON text ----------
def _go_quote(s):
    out='"'
    for ch in s:
        o=ord(ch)
        if ch=='"': out+='\\"'
        elif ch=='\\': out+='\\\\'
        elif ch=='\a': out+='\\a'
        elif ch=='\b': out+='\\b'
        elif ch=='\f': out+='\\f'
        elif ch=='\n': out+='\\n'
        elif ch=='\r': out+='\\r'
        elif ch=='\t': out+='\\t'
        elif ch=='\v': out+='\\v'
        elif o<0x20 or o==0x7f: out+='\\x%02x'%o
        elif not ch.isprintable():
            out+= ('\\u%04x'%o) if o<0x10000 else ('\\U%08x'%o)
        else: out+=ch
    return out+'"'

def _digits_and_n(x):
    r=repr(abs(x)).lower()
    if 'e' in r:
        mant,ex=r.split('e'); ex=int(ex)
    else: mant,ex=r,0
    if '.' in mant:
        a,b=mant.split('.'); digits=a+b; n=len(a)+ex
        stripped=digits.lstrip('0'); lead=len(digits)-len(stripped); n-=lead; digits=stripped
    else:
        digits=mant.lstrip('0') or '0'; n=len(mant)+ex
    digits=digits.rstrip('0') or '0'
    return digits,n
def _go_g_float(x):
    if math.isnan(x): return 'NaN'
    if math.isinf(x): return '+Inf' if x>0 else '-Inf'
    if x==0: return '-0' if math.copysign(1,x)<0 else '0'
    sign='-' if x<0 else ''
    digits,n=_digits_and_n(abs(x)); exp=n-1; k=len(digits)
    if exp < -4 or exp >= 6:
        mant=digits[0]+(('.'+digits[1:]) if k>1 else '')
        return f"{sign}{mant}e{exp:+03d}" if exp<0 or exp<100 else f"{sign}{mant}e+{exp}"
        # Python format for exp sign above gives e-07 etc for negatives via +03d? format %+03d gives -07 for -7? It gives '-07', good. For +6 gives '+06'.
    if n>=k:
        return sign+digits+('0'*(n-k))
    if n>0:
        return sign+digits[:n]+'.'+digits[n:]
    return sign+'0.'+('0'*(-n))+digits

def _scalar_float_str(x):
    return _go_g_float(x)
def _yaml_float_to_json_token(x):
    s=_go_g_float(x)
