def value_to_json(v,unsupported):
    if isinstance(v,TomlDateStr):
        return _go_quote(str(v))
    if isinstance(v,float):
        if math.isnan(v): unsupported.append('NaN'); return 'null'
        if math.isinf(v): unsupported.append('+Inf' if v>0 else '-Inf'); return 'null'
        return js_number_to_string(v)
    if isinstance(v,YMap):
        parts=[]
        for k,val in v.pairs:
            parts.append(_go_quote(str(k))+': '+value_to_json(val,unsupported))
        return '{'+', '.join(parts)+'}'
    if isinstance(v,list):
        return '['+', '.join(value_to_json(x,unsupported) for x in v)+']'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,int): return str(v)
    if v is None: return 'null'
    return _go_quote(str(v))

def toml_to_json_bytes(data,outw):
    text=data.decode('utf-8','surrogateescape') if isinstance(data,bytes) else data
    try:
        root=Parser(text).parse()
    except TomlError:
        raise _panic()
    unsupported=[]
    txt=value_to_json(root,unsupported)
    if unsupported:
        outw(f"json: unsupported value: {unsupported[0]}".encode())
        return None
    return txt.encode('utf-8','surrogateescape')
