# Inject lexical duplicate validation into parse_program by wrapping original method at module load? No: Parser.parse_program in class already returns; validation is invoked from js_engine check/full parse via a separate function below.
def validate_lexical_declarations(prog,src):
    # Raise parserloc error for duplicate lexical declarations in same block and var/lex conflicts.
    def lc(pos): return _line_col_src(src,pos)
    def names_of_pat(p):
        out=[]
        if p is None: return out
        if p.kind=='idpat': out.append((p.a,p.start))
        elif p.kind=='assignpat': out+=names_of_pat(p.a)
        elif p.kind=='rest': out+=names_of_pat(p.a)
        elif p.kind=='objpat':
            for pr in p.a: out+=names_of_pat(pr.a if pr.kind=='rest' else pr.b)
        elif p.kind=='arrpat':
            for e in p.a: out+=names_of_pat(e)
        return out
    def var_names_in(stmts):
        out=[]
        def walk(n):
            if n is None or not isinstance(n,N): return
            if n.kind in ('func','arrow','class','funcdecl','classdecl'): return
            if n.kind=='vardecl' and n.a=='var':
                for pat,init,_ in n.b: out+=names_of_pat(pat)
                return
            for slot in (n.a,n.b,n.c,n.d):
                if isinstance(slot,N): walk(slot)
                elif isinstance(slot,(list,tuple)):
                    for x in slot:
                        if isinstance(x,N): walk(x)
                        elif isinstance(x,(list,tuple)):
                            for y in x:
                                if isinstance(y,N): walk(y)
        for s in stmts: walk(s)
        return out
    def err(name,pos):
        line,col=lc(pos)
        raise JSSyntaxErrorEx(f"Identifier '{name}' has already been declared",pos,'parserloc',line=line,col=col)
    def check_block(stmts,params=()):
        lex={}
        for n,pos in params:
            lex.setdefault(n,pos)
        vars_here={n:p for n,p in var_names_in(stmts)}
        for st in stmts:
            if st.kind=='vardecl' and st.a in ('let','const'):
                for pat,init,_ in st.b:
                    for n,pos in names_of_pat(pat):
                        if n in lex: err(n,pos)
                        if n in vars_here: err(n,pos)
                        lex[n]=pos
            elif st.kind=='classdecl' and st.a:
                n=st.a.a; pos=st.a.start
                if n in lex: err(n,pos)
                if n in vars_here: err(n,pos)
                lex[n]=pos
        for st in stmts: walk_stmt(st)
    def walk_stmt(n):
        if n is None or not isinstance(n,N): return
        if n.kind=='block':
            check_block(n.a); return
        if n.kind in ('func','arrow'):
            params=[]
            plist=n.b if n.kind=='func' else n.a
            for p in plist: params+=names_of_pat(p)
            body=n.c if n.kind=='func' else (n.b if isinstance(n.b,list) else [])
            if isinstance(body,list): check_block(body,params)
            return
        if n.kind=='funcdecl':
            walk_stmt(n.a); return
        if n.kind in ('class','classdecl'):
