# ---------------- tree wrapper ----------------
class TNode:
    __slots__=('j','parent','children','key','key_raw','index','depth','expanded','doc_index')
    def __init__(self,j,parent=None,key=None,index=None,depth=0,doc_index=0):
        self.j=j; self.parent=parent; self.children=[]; self.key=key; self.key_raw=j.key_raw if j else None; self.index=index; self.depth=depth; self.expanded=True; self.doc_index=doc_index
    @property
    def is_container(self):
        return self.j.kind in (JX.OBJECT,JX.ARRAY)
    @property
    def is_empty_container(self):
        return self.is_container and len(self.j.children)==0

def decode_key(jnode):
    if jnode.key_raw is None: return None
    try:
        return JX.decode_json_string_token_go(jnode.key_raw)
    except Exception:
        try: return jnode.key_raw.decode('utf-8','replace')[1:-1]
        except Exception: return ''

def build_tree(jnode,parent=None,key=None,index=None,depth=0,doc_index=0):
    t=TNode(jnode,parent,key,index,depth,doc_index)
    if jnode.kind==JX.OBJECT:
        for ch in jnode.children:
            t.children.append(build_tree(ch,t,decode_key(ch),None,depth+1,doc_index))
    elif jnode.kind==JX.ARRAY:
        for i,ch in enumerate(jnode.children):
            t.children.append(build_tree(ch,t,None,i,depth+1,doc_index))
    return t

def node_path(t):
    if t is None or t.parent is None:
        return ''
    parts=[]
    cur=t
    while cur is not None and cur.parent is not None:
        if cur.parent.j.kind==JX.ARRAY:
            parts.append(f'[{cur.index}]')
        else:
            k=cur.key or ''
            if re.fullmatch(r'[A-Za-z_$][A-Za-z0-9_$]*',k):
                parts.append('.'+k)
            else:
                parts.append(f'[{_json_quote(k)}]')
        cur=cur.parent
    return ''.join(reversed(parts))

def _json_quote(s):
    from fx_format import quote_json_string
    return quote_json_string(s)

# A logical display line
class Line:
    __slots__=('node','closing','depth','expanded_idx')
    def __init__(self,node,closing=False,expanded_idx=0):
        self.node=node; self.closing=closing; self.depth=node.depth if not closing else node.depth; self.expanded_idx=expanded_idx

def full_expanded_lines(roots):
    out=[]
    def rec(t):
        if t.is_container and not t.is_empty_container:
            out.append(Line(t,False,len(out)))
            for c in t.children: rec(c)
            out.append(Line(t,True,len(out)))
        else:
            out.append(Line(t,False,len(out)))
    for r in roots: rec(r)
    return out

def visible_lines(roots):
    full=full_expanded_lines(roots)
    # expanded_idx by (id node, closing)
    idx={(id(l.node),l.closing):l.expanded_idx for l in full}
    out=[]
    def rec(t):
        mine=idx.get((id(t),False),0)
        out.append(Line(t,False,mine))
        if t.is_container and not t.is_empty_container and t.expanded:
            for c in t.children: rec(c)
            out.append(Line(t,True,idx.get((id(t),True),mine)))
    for r in roots: rec(r)
    return out, len(full)

# ---------------- spans / plain text for a line ----------------
# Span: [text(str), style_kind, match_tag]
# style kinds: syntax,key,string,number,bool,null,special,preview,plain

def raw_token_str(b):
    if b is None: return ''
    if isinstance(b,str): return b
    return b.decode('utf-8','surrogateescape')

def scalar_value_span(t):
    j=t.j
    if j.kind==JX.STRING:
        if j.raw_string_value is not None:
            from fx_format import quote_json_string
            return (quote_json_string(j.raw_string_value),'string')
        return (raw_token_str(j.value_raw),'string')
    if j.kind==JX.NUMBER: return (raw_token_str(j.value_raw),'number')
    if j.kind==JX.BOOL: return (raw_token_str(j.value_raw),'bool')
    if j.kind==JX.NULL: return ('null','null')
    if j.kind==JX.SPECIAL: return (raw_token_str(j.value_raw),'special')
    return ('','plain')

def collapsed_preview_spans(t):
    j=t.j
    if j.kind==JX.ARRAY:
        return [('[','syntax'),('…','preview'),(']','syntax')]
    # object
    if not t.children:
        return [('{}','syntax')]
    first=t.children[0]
    # preview text is "key":value compact (no spaces)
    keytok=raw_token_str(first.j.key_raw)
    if first.is_container:
        if first.j.kind==JX.ARRAY: vtxt='[…]'
        elif len(first.children)==0: vtxt='{}'
        else:
            # object preview recursively as {"k":v,…} plain rendering without styles inside preview (preview span is whole)
            vtxt=_preview_plain(first)
    else:
        vtxt=scalar_value_span(first)[0]
    txt=f"{keytok}:{vtxt}"
    spans=[('{','syntax')]
    more=len(t.children)>1
    if more:
        spans.append((txt+',…','preview'))
    else:
        spans.append((txt,'preview'))
    spans.append(('}','syntax'))
    return spans

def _preview_plain(t):
    if not t.is_container:
        return scalar_value_span(t)[0]
    if t.j.kind==JX.ARRAY: return '[…]'
    if not t.children: return '{}'
    f=t.children[0]
    s='{'+raw_token_str(f.j.key_raw)+':'+_preview_plain(f)
    if len(t.children)>1: s+=',…'
    return s+'}'

def line_spans(line,show_sizes=False):
    t=line.node; j=t.j
    spans=[]
    indent='  '*t.depth
    if indent: spans.append((indent,'plain'))
    if line.closing:
        tok='}' if j.kind==JX.OBJECT else ']'
        spans.append((tok,'syntax'))
        if _has_comma_after(t):
            spans.append((',','syntax'))
        return spans
    # key
    if t.parent is not None and t.parent.j.kind==JX.OBJECT:
        spans.append((raw_token_str(j.key_raw),'key'))
        spans.append((': ','syntax'))
    if t.is_container:
        if t.is_empty_container:
            spans.append(('{}' if j.kind==JX.OBJECT else '[]','syntax'))
        elif not t.expanded:
            spans.extend(collapsed_preview_spans(t))
            # collapsed_preview_spans already includes syntax braces; for objects it duplicates? It returns braces + preview; okay.
        else:
            tok='{' if j.kind==JX.OBJECT else '['
            spans.append((tok,'syntax'))
            if show_sizes:
                if j.kind==JX.OBJECT:
                    n=len(t.children); spans.append((f' ({n} key' + ('s' if n!=1 else '') + ')','preview'))
                else:
                    n=len(t.children); spans.append((f' ({n} item' + ('s' if n!=1 else '') + ')','preview'))
            return _maybe_comma(spans,t,opening=True)
    else:
        txt,kind=scalar_value_span(t)
        spans.append((txt,kind))
    return _maybe_comma(spans,t)

def _maybe_comma(spans,t,opening=False):
    if _has_comma_after(t):
        spans.append((',','syntax'))
    return spans
def _has_comma_after(t):
    p=t.parent
    if p is None: return False
    if p.j.kind==JX.ARRAY:
        return t.index is not None and t.index < len(p.children)-1
    # object: position in parent children
    try:
        return p.children.index(t) < len(p.children)-1
    except ValueError:
        return False

def plain_text(spans):
    return ''.join(s for s,_ in spans)

def highlight_span_range(line):
    """Returns (start_char_index, end_char_index) in plain logical line text for cursor token."""
    t=line.node
    spans=line_spans(line)
    # recompute with sizes off for cursor range in rendered (sizes variant handled by caller passing spans?) Caller uses same function on actual spans.
    return None

def _cursor_range_in_spans(line,spans):
    # spans align with line_spans(line, sizes as rendered). Find span to highlight.
    t=line.node
    pos=0
    # Object child: key span is first key-kind span
    if t.parent is not None and t.parent.j.kind==JX.OBJECT and not line.closing:
        for txt,kind in spans:
            if kind=='key': return (pos,pos+len(txt))
            pos+=len(txt)
    if line.closing:
        # first syntax token after indent
        for txt,kind in spans:
            if kind=='syntax': return (pos,pos+len(txt))
            pos+=len(txt)
    if t.is_container:
        # opening bracket (possibly collapsed preview spans start with syntax {)
        for txt,kind in spans:
            if kind=='syntax': return (pos,pos+len(txt))
            pos+=len(txt)
    # scalar: value span (last non-comma significant)
    # choose first span whose kind in value kinds
    for txt,kind in spans:
        if kind in ('string','number','bool','null','special'):
            return (pos,pos+len(txt))
        pos+=len(txt)
    return (0,0)
