            sz=os.get_terminal_size(self.out_fd)
            return sz.columns,sz.lines
        except Exception:
            return 80,24
    def read_key(self):
        # Block for a byte seq, parse one event.
        while not self.buf:
            try:
                chunk=os.read(self.in_fd,4096)
            except OSError:
                return KeyEvent('eof')
            if not chunk:
                return KeyEvent('eof')
