        text=''.join(t for t,_ in spans)
        if not self.wrap or _disp_w(text)<=width:
            return [spans]
        # Only string-like long lines get continuation indent of depth*2. Continuation width is width - indent.
        indent_w=min(line.depth*2,width-1) if width>1 else 0
        segs=[]; cur=[]; cur_w=0; first=True
        # Build a char list with styles
        chars=[]
        for txt,kind in spans:
            for ch in txt: chars.append((ch,kind))
        i=0
        avail=width
        while i<len(chars):
            seg=[]
            if not first:
                seg.append((' '*indent_w,'plain'))
                avail=width-indent_w
            w=0
            while i<len(chars) and w+_disp_w(chars[i][0])<=avail:
                ch,kind=chars[i]
                if seg and seg[-1][1]==kind:
                    seg[-1]=(seg[-1][0]+ch,kind)
                else:
                    seg.append((ch,kind))
                w+=_disp_w(ch); i+=1
            segs.append(seg); first=False
            if avail<=0: break
        return segs or [[]]
    def _clamp_cursor(self):
        if not self.rows: self.cursor=0
        else: self.cursor=max(0,min(self.cursor,len(self.rows)-1))
    def view_height(self):
        w,h=self.term.size()
        if self.mode=='help': return h
        if self.prompt is not None or self.bottom_text is not None or self.pending is not None:
            return max(1,h-2)
        return max(1,h-1)
    def _ensure_visible(self):
        vh=self.view_height()
        if self.cursor<self.top: self.top=self.cursor
        if self.cursor>=self.top+vh: self.top=self.cursor-vh+1
        max_top=max(0,len(self.rows)-vh)
        # In original, top can exceed max_top when the doc ends exactly at bottom? For bottom, top is total-vh if total>vh.
        if self.top>max_top: self.top=max_top
        if self.top<0: self.top=0
    def percent_for_line(self,line):
        total=self.total_expanded
        if total<=0:
            return -9223372036854775808
        if line is None:
            return 1 if total<=100 else 0
        idx=line.expanded_idx
        if idx==0:
            return 1 if total<=100 else 0
        return (idx+1)*100//total

    # ----- frame rendering -----
    def frame(self):
        width,height=self.term.size()
        if self.mode=='help':
            lines=[]
            for i in range(height):
                idx=self.help_offset+i
                txt=HELP_LINES[idx] if idx<len(HELP_LINES) else ''
                lines.append(txt.encode('utf-8'))
            return lines
        if self.mode=='preview':
            return self.preview_frame(width,height)
        self.build_rows(width)
        self._clamp_cursor()
        vh=self.view_height()
        self._ensure_visible()
        out=[]
        for r in range(vh):
            ri=self.top+r
            if ri<len(self.rows):
                out.append(self.render_row(ri,width))
            else:
                out.append(self.cfg.style('~',"90") if self.cfg.colors else self.cfg.style('~','preview'))
                # tilde in grey even when theme styles? In theme0 tui capture likely grey is hardcoded. Our cfg.style with code 90 handles if colors; above tries preview attr nonexistent -> plain. Adjust below.
        # status
        out.append(self.status_line(width))
        if self.prompt is not None:
            out.append(self.prompt_line(width))
        elif self.pending=='yank':
            out.append('(y)value  (p)path  (k)key  (b)key+value'.encode())
        elif self.pending=='view':
            out.append('(s)sizes  (l)line numbers'.encode())
        elif self.bottom_text is not None:
            out.append(self.bottom_text.encode('utf-8','surrogateescape'))
        while len(out)<height:
            out.append(b'')
        return out[:height]
    def render_row(self,row_idx,width):
        line,seg_spans,seg_no=self.rows[row_idx]
        # Margins for line numbers are not included in seg_spans; _segment width accounted margin but render needs prefix. Recompute prefix here matching build_rows margin.
        prefix=b''
        if self.show_lines:
            total=len(self.lines); w=len(str(total))
            if seg_no==0:
                # line number is logical line index in visible lines (not expanded idx?) Original displayed 1..20 visible order.
                num=self.lines.index(line)+1
                txt=f"{num:>{w}}  "
            else:
                txt=' '*(w+2)
            prefix=self.cfg.style(txt,'90') if self.cfg.colors else txt.encode()
        # Search highlight + cursor highlight spans transformation at char level
        spans=self.apply_highlights(line,seg_spans,seg_no,is_cursor=(row_idx==self.cursor))
        out=bytearray(prefix)
        for txt,style in spans:
            out+=self.span_bytes(txt,style)
        return bytes(out)
    def span_bytes(self,txt,style):
        cfg=self.cfg
        if style=='cursor':
            # reverse video regardless of theme colours if terminal output is tty (we only render frames then)
            return b"\x1b[7m"+txt.encode('utf-8','surrogateescape')+b"\x1b[0m"
        if style=='search_other':
            if cfg.colors:
                return b"\x1b[38;5;16m\x1b[103m"+txt.encode('utf-8','surrogateescape')+b"\x1b[0m"
            return txt.encode('utf-8','surrogateescape')
        if style=='search_current':
            return b"\x1b[7m"+txt.encode('utf-8','surrogateescape')+b"\x1b[0m"
        if style=='preview':
            if cfg.colors and cfg.theme!="0":
                return cfg.style(txt,'90')
            return txt.encode('utf-8','surrogateescape')
        if style=='syntax': return cfg.syntax(txt)
        if style=='key': return cfg.key(txt)
        if style in ('string','number','bool','null'): return cfg.st(style,txt)
        if style=='special':
            return cfg.style(txt,"38;5;255;48;5;196") if cfg.colors else txt.encode('utf-8','surrogateescape')
        return txt.encode('utf-8','surrogateescape')
    def apply_highlights(self,line,seg_spans,seg_no,is_cursor):
        # Determine cursor range in whole logical line spans (unsegmented)
        full_spans=line_spans(line,self.show_sizes)
        cur_range=_cursor_range_in_spans(line,full_spans) if is_cursor else None
        # map this segment's char offset in whole line (excluding continuation indent inserted)
        # Reconstruct segment offset by counting prior segments in rows for this line.
        # For simplicity compute all segments again and offsets.
        # seg_spans first element may be continuation indent of spaces plain.
        # Find offset: rows are stored in order; current row index isn't passed, only seg_no. We can compute cumulative plain lengths of segments of this line prior to seg_no using _segment_spans.
        width,_h=self.term.size(); content_width=width-((len(str(len(self.lines)))+2) if self.show_lines else 0)
        allsegs=self._segment_spans(full_spans,content_width,line)
        offset=0
        for si in range(seg_no):
            seg=allsegs[si]
            # continuation indentation for si>0 is synthetic spaces span at start; don't count it in source offset if si+1 segment starts with it handled in loop below.
            for txt,kind in seg:
                offset+=len(txt)
            if si>=0 and si+1 < len(allsegs):
                # next segment has indent prefix not part of source; the loop counting previous segments included their own inserted indent for si>0 - adjust after loop
                pass
        # Adjust: for prior continuation segments, inserted indent (line.depth*2) was counted but is not source. Those segments are si=1..seg_no-1.
        if seg_no>1:
            offset -= (seg_no-1)*min(line.depth*2,content_width-1 if content_width>1 else 0)
        # Now split seg_spans by character with styles, marking cursor/search
        # Search ranges for this node: list of ranges in logical line coordinates (computed in _search_ranges_for_line)
        search_ranges=self._search_ranges_for_line(line)
        cur_hit=None
        if self.search_hits and 0<=self.search_index<len(self.search_hits):
            h=self.search_hits[self.search_index]
            if h.node is line.node and not line.closing:
                cur_hit=h
        # Build char list of this segment with source positions (skip synthetic indent at start)
        chars=[]
        src_pos=offset
        for idx,(txt,kind) in enumerate(seg_spans):
            if seg_no>0 and idx==0 and kind=='plain' and set(txt)=={' '}:
                for ch in txt: chars.append((ch,kind,None))
                continue
            for ch in txt:
                chars.append((ch,kind,src_pos)); src_pos+=1
        # apply styles per char priority: search current > cursor > search other > base
        out=[]
        for ch,kind,pos in chars:
            style=kind
            if pos is not None:
                for rr in search_ranges:
                    if rr[0]<=pos<rr[1]:
                        style='search_other'; break
                if cur_hit is not None:
                    cr=self._range_for_hit(line,cur_hit)
                    if cr and cr[0]<=pos<cr[1]: style='search_current'
                if is_cursor and cur_range and not (cur_hit is not None):
                    if cur_range[0]<=pos<cur_range[1]: style='cursor'
                elif is_cursor and cur_range and cur_hit is not None:
                    # If this segment is a continuation of a scalar whose key is on first segment, cursor range in first segment only; in continuation segments original highlights value segment. That range is value span not key when seg>0? Handle: if seg_no>0 and pos inside scalar value span (i.e., beyond key range), highlight char if it belongs to same scalar token as first segment's value.
                    # Our cur_range for object entry keys is only key; continuation highlight in original was the string remainder -> because cursor token for a wrapped segment becomes the piece of scalar. Apply cursor to non-plain chars in continuation if no search.
                    if seg_no>0 and kind in ('string','number','bool','null','special'):
                        style='cursor'
            else:
                # synthetic indent no style
                style=kind
            if out and out[-1][1]==style:
                out[-1]=(out[-1][0]+ch,style)
            else:
                out.append((ch,style))
        # Segment continuation cursor special case above doesn't trigger when cur_hit exists; original search current segment already marked.
        if is_cursor and seg_no>0 and cur_hit is None:
            # chars already processed: our logic inside cur_range won't cover continuation value range if cursor range was key on first segment. Re-mark result spans of value kind as cursor.
            newout=[]
            for ch,kind,pos in chars:
                style=kind
                if pos is not None and kind in ('string','number','bool','null','special'):
                    style='cursor'
                if newout and newout[-1][1]==style: newout[-1]=(newout[-1][0]+ch,style)
                else: newout.append((ch,style))
            # preserve search_other applied above by reapplying ranges if any
            if search_ranges and cur_hit is None:
                return out
            return newout
        return out
    def _range_for_hit(self,line,hit):
        # Map hit subject start/end to logical line char range.
        spans=line_spans(line,self.show_sizes)
        pos=0
        if hit.field=='key':
            for txt,kind in spans:
                if kind=='key':
                    # hit positions are inside raw key token string (subject is raw token incl quotes)
                    return (pos+hit.start,pos+hit.end)
                pos+=len(txt)
            return None
        # value: find value span for this node (scalar token or opening brace token)
        if line.node.is_container:
            for txt,kind in spans:
                if kind=='syntax' and txt in ('{','['):
                    return (pos+hit.start,pos+hit.end)
                pos+=len(txt)
            return None
        for txt,kind in spans:
            if kind in ('string','number','bool','null','special'):
                return (pos+hit.start,pos+hit.end)
            pos+=len(txt)
        return None
    def _search_ranges_for_line(self,line):
        ranges=[]
        for h in self.search_hits:
            if h.node is line.node and not line.closing:
                r=self._range_for_hit(line,h)
                if r: ranges.append(r)
        return ranges
    def status_line(self,width):
        if self.mode=='preview':
            path=node_path(self.current_node()) if self.current_node() else ''
            right=self.data_name
            txt=(path+' '*(max(0,width-len(path)-len(right)))+right)[:width]
        else:
            line=self.current_line()
            path=node_path(line.node) if line else ''
            pct=self.percent_for_line(line)
            right=f"{pct}%"
            if self.data_name: right+=f" {self.data_name}"
            pad=max(0,width-len(path)-len(right))
            txt=path+' '*pad+right
        b=txt.encode('utf-8','surrogateescape')
        # status style black on white (30;47) when colours enabled; in no-colour terminals termenv could still produce reverse-ish (?) BubbleTea/tcell uses style attributes regardless of color profile - tmux captures showed 30;47. Use that if stderr is tty, which is when frames render.
        return b"\x1b[30m\x1b[47m"+b.ljust(width)+b"\x1b[0m"
    def prompt_line(self,width):
        p=self.prompt; txt=p['prefix']+p['text']
        return txt.encode('utf-8','surrogateescape')
    def preview_frame(self,width,height):
        node=self.current_node()
        try:
            text=render_raw_node_top(node.j,PrintConfig(inline=self.cfg.inline,theme=self.cfg.theme,colors=self.cfg.colors)).decode('utf-8','surrogateescape')
        except Exception:
            text=''
        plines=text.split('\n')
        # wrap lines simply by slicing plain bytes spans? Preview of long strings is a raw string (not wrapped in original? It likely uses Stringify with viewport and wraps). Use plain wrapping by chars.
        rows=[]
        for pl in plines:
            if len(pl)<=width: rows.append(pl)
            else:
                rows.extend(pl[i:i+width] for i in range(0,len(pl),width))
        vh=max(1,height-1)
        out=[]
        for i in range(vh):
            idx=self.preview_offset+i
            out.append((rows[idx] if idx<len(rows) else '').encode('utf-8','surrogateescape'))
        out.append(self.status_line(width))
        return out
