# ---------------- terminal key input ----------------
class KeyEvent:
    __slots__=('name','text','mouse')
    def __init__(self,name,text=None,mouse=None):
        self.name=name; self.text=text; self.mouse=mouse
    def __repr__(self): return f"Key({self.name!r} {self.text!r} {self.mouse})"

def _disp_w(s):
    from jsonx import _disp_width_text
    return _disp_width_text(s)

class Terminal:
    def __init__(self,input_is_stdin):
        self.in_fd=None
        self.in_file=None
        self.orig=None
        self.input_is_stdin=input_is_stdin
        self.out_fd=2
        self.buf=b''
    def open_input(self):
        if self.input_is_stdin:
            self.in_fd=0; self.in_file=sys.stdin.buffer
            return True
        try:
            self.in_fd=os.open('/dev/tty',os.O_RDWR)
            self.in_file=os.fdopen(os.dup(self.in_fd),'rb',buffering=0)
            return True
        except OSError:
            return False
    def set_raw(self):
        if self.in_fd is None: return
        try:
            self.orig=termios.tcgetattr(self.in_fd)
            tty.setraw(self.in_fd)
        except Exception:
            self.orig=None
    def restore(self):
        if self.orig is not None:
            try: termios.tcsetattr(self.in_fd,termios.TCSADRAIN,self.orig)
            except Exception: pass
            self.orig=None
    def write(self,b):
        try:
            os.write(self.out_fd,b)
        except OSError:
            pass
    def size(self):
        try:
            sz=os.get_terminal_size(self.out_fd)
            return sz.columns,sz.lines
        except Exception:
            return 80,24
    def read_key(self):
        # Block for a byte seq, parse one event.
        while not self.buf:
            try:
                chunk=os.read(self.in_fd,4096)
            except OSError:
                return KeyEvent('eof')
            if not chunk:
                return KeyEvent('eof')
            self.buf+=chunk
        return self._parse_one()
    def poll_read_more(self):
        # after ESC, try to read more available bytes briefly
        try:
            r,_,_=select.select([self.in_fd],[],[],0.01)
            if r:
                data=os.read(self.in_fd,4096)
                if data: self.buf+=data; return True
        except Exception:
            pass
        return False
    def _parse_one(self):
        b=self.buf
        if b.startswith(b'\x1b'):
            if len(b)==1:
                # may be lone escape or start of sequence; poll briefly
                if self.poll_read_more():
                    b=self.buf
                else:
                    self.buf=b''; return KeyEvent('esc')
            if len(b)>=2 and b[1:2]==b'[':
                # bracketed paste / mouse / csi
                if b.startswith(b'\x1b[200~'):
                    end=b.find(b'\x1b[201~')
                    if end<0:
                        # incomplete; wait for more (simplify: read more)
                        if self.poll_read_more():
                            return self._parse_one()
                        txt=b[6:].decode('utf-8','surrogateescape'); self.buf=b''; return KeyEvent('paste',txt)
                    txt=b[6:end].decode('utf-8','surrogateescape'); self.buf=b[end+6:]; return KeyEvent('paste',txt)
                if b.startswith(b'\x1b[<'):
                    m=re.match(br'\x1b\[<(\d+);(\d+);(\d+)([Mm])',b)
                    if m:
                        self.buf=b[m.end():]
                        return KeyEvent('mouse',mouse=(int(m.group(1)),int(m.group(2)),int(m.group(3)),m.group(4).decode()))
                    # incomplete
                    if self.poll_read_more(): return self._parse_one()
                return self._parse_csi()
            if len(b)>=2 and b[1:2]==b'O':
                if len(b)<3:
                    if self.poll_read_more(): return self._parse_one()
                    self.buf=b''; return KeyEvent('esc')
                ch=chr(b[2]); self.buf=b[3:]
                mp={'P':'f1','Q':'f2','R':'f3','S':'f4','A':'up','B':'down','C':'right','D':'left','H':'home','F':'end'}
                return KeyEvent(mp.get(ch,'esc'))
            # Alt+char or lone esc followed by char: deliver esc then char next time
            self.buf=b[1:]
            return KeyEvent('esc')
        first=b[0]
        if first==3: self.buf=b[1:]; return KeyEvent('ctrl+c')
        if first==26: self.buf=b[1:]; return KeyEvent('ctrl+z')
        if first==7: self.buf=b[1:]; return KeyEvent('ctrl+g')
        if first==4: self.buf=b[1:]; return KeyEvent('ctrl+d')
        if first==21: self.buf=b[1:]; return KeyEvent('ctrl+u')
        if first==13 or first==10: self.buf=b[1:]; return KeyEvent('enter')
        if first==9: self.buf=b[1:]; return KeyEvent('tab')
        if first in (127,8): self.buf=b[1:]; return KeyEvent('backspace')
        if first==0: self.buf=b[1:]; return KeyEvent('ctrl+space')
        if first<32:
            self.buf=b[1:]; return KeyEvent(f'ctrl+{chr(first+96)}')
        # utf-8 char
        # consume one unicode character if possible, otherwise one byte as surrogateescape char
        for ln in range(1,min(5,len(b)+1)):
            try:
                txt=b[:ln].decode('utf-8')
                if len(txt)==1:
                    self.buf=b[ln:]; return KeyEvent('char',txt)
            except Exception:
                continue
        txt=chr(b[0]); self.buf=b[1:]; return KeyEvent('char',txt)
    def _parse_csi(self):
        b=self.buf
        # CSI: ESC [ params (0x30-0x3f) intermediates (0x20-0x2f) final (0x40-0x7e)
        i=2
        while i<len(b) and 0x30<=b[i]<=0x3f: i+=1
        while i<len(b) and 0x20<=b[i]<=0x2f: i+=1
        if i>=len(b):
            if self.poll_read_more(): return self._parse_one()
            self.buf=b''; return KeyEvent('esc')
        final=chr(b[i]); params=b[2:i].decode('ascii','ignore')
        self.buf=b[i+1:]
        # split params
        parts=params.split(';') if params else []
        def pv(n,default=1):
            try: return int(parts[n]) if parts[n] else default
            except Exception: return default
        shift = any(len(parts)>1 and parts[1] not in ('','1') for _ in [0])
        # modifier 2 shift, etc. Map with shift-specific names used by model.
        mod=pv(1,1) if len(parts)>1 else 1
        suffix='_shift' if mod==2 else ''
        mp={'A':'up','B':'down','C':'right','D':'left','H':'home','F':'end','Z':'shift+tab'}
        if final in mp:
            name=mp[final]
            if suffix and final in 'ABCD':
                return KeyEvent('shift+'+name)
            return KeyEvent(name)
        if final=='~':
            code=pv(0,0)
            m2={1:'home',2:'insert',3:'delete',4:'end',5:'pgup',6:'pgdown',7:'home',8:'end',11:'f1',12:'f2',13:'f3',14:'f4',15:'f5',17:'f6',18:'f7',19:'f8',20:'f9',21:'f10',23:'f11',24:'f12'}
            return KeyEvent(m2.get(code,'unknown'))
        return KeyEvent('unknown')

