# ---------------- app model ----------------
class App:
    def __init__(self,roots,filename,cfg,term,data_name='',raw_mode=False):
        self.roots=roots; self.filename=filename; self.data_name=data_name; self.cfg=cfg; self.term=term
        self.cursor=0  # index into display rows
        self.top=0
        self.wrap=True
        self.show_sizes=False; self.show_lines=False
        self.mode=None  # None | help | preview | prompts handled by prompt field
        self.help_offset=0
        self.preview_offset=0
        self.prompt=None # dict kind,text
        self.bottom_text=None  # string for bottom second line (search result / menus are prompts)
        self.pending=None  # 'yank','view','delete' pending choice
        self.search_pattern=None; self.search_hits=[]; self.search_index=-1; self.search_message=None
        self.goto_candidate=None
        self.quit=False; self.print_and_quit=False
        self.raw_mode=raw_mode
        self.lines=[]; self.total_expanded=0
        self.rows=[]  # list of Row(logical_line, segment_text_spans_rendered info)
        self._rebuild()
        if raw_mode and self.rows:
            # Follow tail of raw input
            self.cursor=len(self.rows)-1
            self._ensure_visible()
    def _rebuild(self,keep_node=None):
        if keep_node is None and self.rows:
            cur=self.current_line(); keep_node=(cur.node,cur.closing) if cur else None
        elif keep_node is not None:
            keep_node=(keep_node.node,keep_node.closing)
        self.lines,self.total_expanded=visible_lines(self.roots)
        # rows rebuilt lazily in frame based on width
        self.rows=[]
        self._rows_width=None
        if keep_node:
            # will position after rows built in frame; store target
            self._pending_cursor_node=keep_node
    def current_line(self):
        if not self.rows: return None
        if self.cursor<0: self.cursor=0
        if self.cursor>=len(self.rows): self.cursor=len(self.rows)-1
        return self.rows[self.cursor][0]
    def current_node(self):
        l=self.current_line(); return l.node if l else None
    def build_rows(self,width):
        if self._rows_width==width and self.rows:
            return
        rows=[]
        content_width=width
        margin_w=0
        if self.show_lines and self.lines:
            margin_w=len(str(len(self.lines)))+2
            content_width=max(1,width-margin_w)
        for idx,line in enumerate(self.lines):
            spans=line_spans(line,self.show_sizes)
            # wrap / segment
            segs=self._segment_spans(spans,content_width,line)
            for si,seg_spans in enumerate(segs):
                rows.append((line,seg_spans,si))
        self.rows=rows; self._rows_width=width
        pending=getattr(self,'_pending_cursor_node',None)
        if pending:
            self._pending_cursor_node=None
            for i,(l,_,si) in enumerate(rows):
                if l.node is pending[0] and l.closing==pending[1] and si==0:
                    self.cursor=i; break
            self._clamp_cursor(); self._ensure_visible()
    def _segment_spans(self,spans,width,line):
        text=''.join(t for t,_ in spans)
        if not self.wrap or _disp_w(text)<=width:
            return [spans]
        # Only string-like long lines get continuation indent of depth*2. Continuation width is width - indent.
        indent_w=min(line.depth*2,width-1) if width>1 else 0
