        if not target_str.startswith('#/'): return
        parts=[p.replace('~1','/').replace('~0','~') for p in target_str[2:].split('/')]
        for root in self.roots:
            cur=root; ok=True
            for part in parts:
                nxt=None
                for c in cur.children:
                    if cur.j.kind==JX.ARRAY:
                        if str(c.index)==part: nxt=c; break
                    elif c.key==part: nxt=c; break
                if nxt is None: ok=False; break
                cur=nxt
            if ok:
                # expand ancestors
                anc=cur.parent
                while anc is not None: anc.expanded=True; anc=anc.parent
                self.lines=[]; self.rows=[]; self._rows_width=None; self._rebuild(); self.build_rows(*self.term.size()); self.goto_line_node(cur); return
    # ----- yank -----
    def yank_text(self,choice):
        node=self.current_node()
        if node is None: return None
        path=node_path(node)
        value_text=self.node_stringify(node)
        key=node.key if node.key is not None else (str(node.index) if node.index is not None else '')
        if choice=='y': return value_text
        if choice=='p': return path
        if choice=='k': return key
        if choice=='b': return f"{key}: {value_text}"
        return None
    def node_stringify(self,node):
        return render_raw_node_top(node.j,PrintConfig(inline=self.cfg.inline,theme='0',colors=False)).decode('utf-8','surrogateescape')
    def copy_to_clipboard(self,text):
        data=text.encode('utf-8','surrogateescape')
        import shutil
        try:
            if os.environ.get('WAYLAND_DISPLAY') and shutil.which('wl-copy'):
                subprocess.run(['wl-copy'],input=data,timeout=2)
            elif shutil.which('xclip'):
                subprocess.run(['xclip','-in','-selection','clipboard'],input=data,timeout=2)
            elif shutil.which('xsel'):
                subprocess.run(['xsel','--input','--clipboard'],input=data,timeout=2)
            elif shutil.which('pbcopy'):
                subprocess.run(['pbcopy'],input=data,timeout=2)
            elif shutil.which('clip.exe'):
                subprocess.run(['clip.exe'],input=data,timeout=2)
        except Exception:
            pass

