    def subject_for(self,node):
        subs=[]
        if node.parent is not None and node.parent.j.kind==JX.OBJECT:
            subs.append(('key',raw_token_str(node.j.key_raw)))
        j=node.j
        if j.kind==JX.OBJECT: subs.append(('value','{'))
