        elif j.kind==JX.STRING:
            subs.append(('value',raw_token_str(j.value_raw) if j.raw_string_value is None else _json_quote(j.raw_string_value)))
        elif j.kind in (JX.NUMBER,JX.BOOL,JX.SPECIAL): subs.append(('value',raw_token_str(j.value_raw)))
