            rx=re.compile(pattern,re.IGNORECASE)
        except re.error as e:
            return f"error parsing regexp: {self._go_regex_error(pattern,e)}"
        # Traverse all nodes in document order (full tree)
        def rec(t):
            yield t
            for c in t.children: yield from rec(c)
        allnodes=[]
        for r in self.roots: allnodes.extend(list(rec(r)))
        for node in allnodes:
            for field,subj in self.subject_for(node):
                for m in rx.finditer(subj):
                    if m.end()==m.start():
                        # empty match counts once per node/subject broadly; avoid infinite
                        self.search_hits.append(SearchHit(node,field,m.start(),m.end()))
                        break
                    self.search_hits.append(SearchHit(node,field,m.start(),m.end()))
        if not self.search_hits:
            self.bottom_text=f"/{pattern}/i"+' '*(max(0,self.term.size()[0]-len(pattern)-3-len('not found')))+'not found'
            # Simpler formatting done in render bottom via bottom_text already; if width changes not updated. Use a formatted helper instead stored raw info in bottom_text computed each frame? Keep state and calculate in frame? bottom_text is static string. Recompute at current width here.
            return None
        # Find first hit at or after current expanded line index? Original starts searching from top if fresh from root; from current position? When opening / after navigating earlier, it likely searches forward from current cursor (inclusive?). Choose first hit whose expanded line idx >= current line expanded idx, else first.
        cur_idx=self.current_line().expanded_idx if self.current_line() else 0
        full=full_expanded_lines(self.roots); pos={id(l.node):l.expanded_idx for l in full if not l.closing}
        chosen=0
        for i,h in enumerate(self.search_hits):
            if pos.get(id(h.node),0)>=cur_idx:
